        // 1. Base Exponential Scaling (Mũ 1.15)
        let baseReward = Math.floor(50 * Math.pow(newLevel, 1.15));

        // 2. Random Bonus (0% - 20%)
        const rngBonus = 1 + Math.random() * 0.2;
        let coinReward = Math.floor(baseReward * rngBonus);

