              dateList.push({ date: d, dayStr: localDateStr });
        }

        if (!profile?.id || profile.id === 'undefined') {
            const emptyHistory = dateList.map((d, index) => ({
                d: index === 6 ? 'HN' : dayLabels[d.date.getDay()],
                ml: 0,
                isToday: index === 6,
            }));
            setWeeklyHistory(emptyHistory);
