    const actionId = notificationAction.actionId;

    // 🚀 1. Xử lý NÚT BẤM Nhận thưởng Nhiệm vụ / Thử thách từ ngoài màn hình khóa
    if (actionId === 'claim_quest' && extra?.type === 'quest' && extra?.id) {
