import { useState, type FormEvent } from 'react';
import { ChevronLeft, Lock } from 'lucide-react';
import { Toaster, toast } from 'sonner';
import { Capacitor } from '@capacitor/core';
import { Browser } from '@capacitor/browser';
import { supabase } from '@/lib/supabase';

const GOOGLE_CALENDAR_SCOPE = 'https://www.googleapis.com/auth/calendar.readonly';

interface LoginScreenProps {
  onBack: () => void;
  initialEmail?: string;
}

export default function LoginScreen({ onBack, initialEmail = '' }: LoginScreenProps) {
  const [loginEmail, setLoginEmail] = useState(initialEmail);
  const [loginPass, setLoginPass] = useState('');
  const [isSubmittingLogin, setIsSubmittingLogin] = useState(false);

  const handleLogin = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (isSubmittingLogin) return;
    if (!loginEmail || !loginPass) { toast.error("Vui lòng nhập Email và Mật khẩu!"); return; }
    setIsSubmittingLogin(true);
    const toastId = toast.loading("Đang xác thực...");
    try {
      const { error } = await supabase!.auth.signInWithPassword({ email: loginEmail.toLowerCase().trim(), password: loginPass });
      if (error) throw error;
      toast.success("Đăng nhập thành công! 👋", { id: toastId });
    } catch (err: any) {
      toast.error(err.message === 'Invalid login credentials' ? 'Email hoặc mật khẩu không đúng!' : err.message, { id: toastId });
    } finally { setIsSubmittingLogin(false); }
  };

  const handleGoogleLogin = async () => {
    try {
      const { data, error } = await supabase!.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: Capacitor.isNativePlatform() ? 'digiwell://login-callback' : window.location.origin,
          skipBrowserRedirect: Capacitor.isNativePlatform(),
          scopes: GOOGLE_CALENDAR_SCOPE,
          queryParams: {
            access_type: 'offline',
            prompt: 'consent',
            include_granted_scopes: 'true',
          },
        }
      });
      if (error) throw error;
      if (data?.url && Capacitor.isNativePlatform()) await Browser.open({ url: data.url });
    } catch (err: any) {
      toast.error("Lỗi kết nối Google: " + err.message);
    }
  };

  const handleAppleLogin = async () => {
    try {
      const { data, error } = await supabase!.auth.signInWithOAuth({
        provider: 'apple',
        options: {
          redirectTo: Capacitor.isNativePlatform() ? 'digiwell://login-callback' : window.location.origin,
          skipBrowserRedirect: Capacitor.isNativePlatform()
        }
      });
      if (error) throw error;
      if (data?.url && Capacitor.isNativePlatform()) await Browser.open({ url: data.url });
    } catch (err: any) {
      toast.error("Lỗi kết nối Apple: " + err.message);
    }
  };

  return (
    <div className="flex flex-col min-h-screen max-w-md mx-auto font-sans bg-slate-950">
      <Toaster position="top-center" theme="dark" richColors />
      <div className="p-6 pt-14">
        <button onClick={onBack} className="mb-10 p-2 rounded-xl bg-slate-900/60 backdrop-blur-xl border border-white/5 text-slate-400 inline-flex active:scale-95 transition-all duration-200 ease-out hover:text-white">
          <ChevronLeft size={20} />
        </button>

        <h2 className="text-3xl font-black text-white mb-8">Đăng nhập</h2>

        <form onSubmit={handleLogin} className="space-y-4">
          <div>
            <label className="text-xs text-slate-400 font-semibold uppercase tracking-wider mb-2 block">Email</label>
            <input type="email" placeholder="your@email.com" value={loginEmail} onChange={e => setLoginEmail(e.target.value)} disabled={isSubmittingLogin} className="w-full p-4 rounded-2xl bg-slate-900/60 backdrop-blur-xl border border-white/5 text-white placeholder-slate-500 outline-none focus:ring-2 focus:ring-cyan-500/50 focus:border-transparent transition-all duration-200 ease-out disabled:opacity-50 text-sm" />
          </div>
          <div>
            <label className="text-xs text-slate-400 font-semibold uppercase tracking-wider mb-2 block">Mật khẩu</label>
            <div className="relative">
              <input type="password" placeholder="••••••••" value={loginPass} onChange={e => setLoginPass(e.target.value)} disabled={isSubmittingLogin} className="w-full p-4 pl-12 rounded-2xl bg-slate-900/60 backdrop-blur-xl border border-white/5 text-white placeholder-slate-500 outline-none focus:ring-2 focus:ring-cyan-500/50 focus:border-transparent transition-all duration-200 ease-out disabled:opacity-50 text-sm" />
              <Lock className="w-4 h-4 absolute left-4 top-4 text-slate-500" />
            </div>
          </div>
          <button type="submit" disabled={isSubmittingLogin} className="w-full py-4 rounded-2xl font-semibold text-slate-950 text-sm mt-2 disabled:opacity-50 active:scale-95 transition-all duration-200 ease-out shadow-[0_0_15px_rgba(6,182,212,0.4)] hover:shadow-[0_0_25px_rgba(6,182,212,0.6)]" style={{ background: isSubmittingLogin ? '#334155' : '#06b6d4' }}>
            {isSubmittingLogin ? <span className="animate-pulse">Đang xác thực...</span> : "Đăng nhập →"}
          </button>
        </form>

        <div className="mt-6 flex items-center justify-between text-xs text-slate-500">
          <hr className="w-full border-slate-700" /><span className="px-3 font-bold tracking-widest">HOẶC</span><hr className="w-full border-slate-700" />
        </div>

        <button onClick={handleGoogleLogin} className="w-full py-4 rounded-2xl font-bold text-white text-sm mt-6 border border-white/5 bg-slate-900/60 backdrop-blur-xl hover:bg-slate-800/80 active:scale-95 transition-all duration-200 ease-out flex items-center justify-center gap-2">
          <img src="https://www.svgrepo.com/show/475656/google-color.svg" alt="Google" className="w-5 h-5" />
          Đăng nhập bằng Google
        </button>
        
        <button onClick={handleAppleLogin} className="w-full py-4 rounded-2xl font-bold text-white text-sm mt-3 border border-white/5 bg-slate-900/60 backdrop-blur-xl hover:bg-slate-800/80 active:scale-95 transition-all duration-200 ease-out flex items-center justify-center gap-2">
          <img src="https://www.svgrepo.com/show/511330/apple-173.svg" alt="Apple" className="w-5 h-5" style={{ filter: 'invert(1)' }} />
          Đăng nhập bằng Apple
        </button>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Swords, Calendar, Trophy, Gift, Sparkles, Target } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { playSuccessSound } from '@/lib/audio';
import { QuestCard, QuestCardSkeleton } from '@/components/QuestCard';
import { useQuests } from '@/hooks/useQuests';
import type { UserQuest } from '@/config/questConfig';
import { toast } from 'sonner';
import { resolveQuestProgress } from '@/lib/questProgress';

interface QuestPageProps {
  userId: string;
  userLevel?: number;
  streak?: number;
  waterToday?: number;
  logCount?: number;
  onRewardClaimed: (exp: number, wp: number) => void;
}

const tabConfig = {
  daily: { icon: Calendar, label: 'Hàng ngày', color: 'cyan' },
  weekly: { icon: Target, label: 'Hàng tuần', color: 'purple' },
  level: { icon: Trophy, label: 'Thành tựu', color: 'amber' }, // Map achievement to level
};

const QuestPage = ({ userId, userLevel = 1, streak = 0, waterToday = 0, logCount = 0, onRewardClaimed }: QuestPageProps) => {
  const [filter, setFilter] = useState<'daily' | 'weekly' | 'level'>('daily');
  const [claimingId, setClaimingId] = useState<string | null>(null);

  // Use the new useQuests hook
  const { quests, loading, claimQuest, refetch } = useQuests(userId, userLevel);

  const handleClaimReward = async (userQuestId: string) => {
    if (claimingId) return;

    const userQuest = quests.find(q => q.id === userQuestId);
    if (!userQuest) {
      toast.error("Không tìm thấy nhiệm vụ này!");
      return;
    }

    // Validate user ID exists
    if (!userId || userId === 'undefined') {
      toast.error('Vui lòng đăng nhập lại');
      return;
    }

    setClaimingId(userQuestId); // Use user_quest_id for claiming

    const toastId = toast.loading('Đang nhận thưởng...');

    try {
      const result = await claimQuest(userQuestId);
      if (result) {
        console.log('[QuestPage] Claim successful, updating UI');
        toast.success(
          `🎁 +${userQuest.quest.reward_exp} EXP | 💰 +${userQuest.quest.reward_coins} Coins!`,
          {
            id: toastId,
            icon: '🎉',
          }
        );

        playSuccessSound();
        onRewardClaimed(userQuest.quest.reward_exp, userQuest.quest.reward_coins);
      } else {
        throw new Error('Claim failed');
      }
    } catch (err: any) {
      toast.error(err.message || 'Lỗi nhận thưởng', { id: toastId });
    } finally {
      setClaimingId(null);
    }
  };

  const filteredQuests = useMemo(() => {
    const filtered = quests.filter(q => (q.quest as any)?.type === filter);
    
    // Sắp xếp ưu tiên: Hoàn thành chưa nhận thưởng > Đang thực hiện > Đã nhận thưởng
    return filtered.sort((a, b) => {
      const getDynamicProgress = (q: UserQuest) => {
        const resolved = resolveQuestProgress(q.quest, {
          waterToday,
          logCountToday: logCount,
          streak,
          level: userLevel,
        });

        return Math.max(Number(q.progress || 0), resolved.progress);
      };
      
      const getPriority = (q: UserQuest) => {
        if (q.status === 'claimed') return 2;
        const p = getDynamicProgress(q);
        if (q.status === 'completed' || p >= q.quest.condition_value) return 0;
        return 1;
      };

      const priorityDiff = getPriority(a) - getPriority(b);
      
      if (priorityDiff === 0) {
        // Ưu tiên 2: Chèn giữa - Xếp theo tỉ lệ % hoàn thành (Tiến độ cao hơn xếp trước)
        const pA = getDynamicProgress(a);
        const pB = getDynamicProgress(b);
        const ratioA = a.quest.condition_value ? (pA / a.quest.condition_value) : 0;
        const ratioB = b.quest.condition_value ? (pB / b.quest.condition_value) : 0;
        
        if (ratioA !== ratioB) {
          return ratioB - ratioA; // Sắp xếp giảm dần theo %
        }
        
        // Ưu tiên 3: Nếu % tiến độ bằng nhau, sắp xếp từ dễ đến khó theo mốc
        return (a.quest.condition_value || 0) - (b.quest.condition_value || 0);
      }
      
      return priorityDiff;
    });
  }, [quests, filter, waterToday, logCount, streak, userLevel]);

  const stats = useMemo(() => {
    const total = filteredQuests.length;
    const completed = filteredQuests.filter(q => q.status === 'completed').length;
    const claimed = filteredQuests.filter(q => q.status === 'claimed').length;

    return { total, completed, claimed };
  }, [filteredQuests]);

  const currentTab = tabConfig[filter];

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-300">

      {/* HEADER */}
      <div className="px-6 pt-6">
        <p className="text-xs uppercase tracking-wider text-slate-400 mb-1">
          Quest System
        </p>

        <h1 className="text-3xl font-bold text-white flex items-center gap-3">
          Nhiệm vụ
          <Swords size={28} className="text-cyan-400" />
        </h1>

        {/* mini stats */}
        <div className="mt-3 flex gap-4 text-xs text-slate-400">
          <span>📦 {stats.total}</span>
          <span>⚔️ {stats.completed}</span>
          <span>🎁 {stats.claimed}</span>
        </div>
      </div>

      {/* TABS */}
      <div className="mx-4 p-1 rounded-xl bg-slate-900/80 border border-slate-800 flex">
        {Object.entries(tabConfig).map(([key, cfg]) => {
          const Icon = cfg.icon;
          const active = filter === key;

          return (
            <button
              key={key}
              onClick={() => setFilter(key as 'daily' | 'weekly' | 'level')}
              className={`flex-1 py-2.5 text-xs font-bold rounded-lg flex items-center justify-center gap-2 transition-all
                ${
                  active
                    ? key === 'daily'
                      ? 'bg-cyan-500/20 text-cyan-400'
                      : key === 'weekly'
                      ? 'bg-purple-500/20 text-purple-400'
                      : 'bg-amber-500/20 text-amber-400'
                    : 'text-slate-400 hover:text-slate-200'
                }
              `}
            >
              <Icon size={14} />
              {cfg.label}
            </button>
          );
        })}
      </div>



      {/* BODY */}
      {loading ? (
        <div className="px-4 space-y-3">
          <QuestCardSkeleton />
          <QuestCardSkeleton />
          <QuestCardSkeleton />
        </div>
      ) : (
        <motion.div layout className="px-4 space-y-3">
          <AnimatePresence mode="popLayout">
            {filteredQuests.length > 0 ? (
              filteredQuests.map((userQuest) => (
                <motion.div
                  key={userQuest.id}
                  layout
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.98 }}
                  transition={{ duration: 0.2 }}
                >
                  <QuestCard
                    userQuest={userQuest}
                    onClaim={handleClaimReward}
                    isClaiming={claimingId === userQuest.id}
                    userLevel={userLevel}
                    streak={streak}
                    waterToday={waterToday}
                    logCount={logCount}
                  />
                </motion.div>
              ))
            ) : (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
