import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Sparkles } from 'lucide-react';

interface AvatarFrameProps {
  level: number;
  avatarUrl: string | null;
  size?: 'sm' | 'md' | 'lg' | 'xl';
  showBadge?: boolean;
  nickname?: string;
}

export function getRankTitle(level: number): string {
  if (level >= 100) return "Thủy Thần";
  if (level >= 70) return "Huyền Thoại";
  if (level >= 50) return "Tinh Anh";
  if (level >= 30) return "Chiến Binh";
  if (level >= 15) return "Người Kiên Trì";
  return "Tân Binh";
}

// Hàm lấy Cấu hình Hiệu ứng dựa trên Level
export const getFrameEffects = (level: number) => {
  const safeLevel = Math.max(level, 1);

  // Mặc định: Tân Binh (< 15) - Chỉ border mờ
  let config = {
    title: "TÂN BINH",
    textColor: "text-slate-400",
    badgeColor: "bg-slate-700",
    frameClasses: "border-slate-700 shadow-none",
    effects: null as React.ReactNode,
  };

  // Cấp 15-29: Người Kiên Trì - Border sáng nhẹ
  if (safeLevel >= 15) {
    config = {
      title: "KIÊN TRÌ",
      textColor: "text-blue-400",
      badgeColor: "bg-blue-900",
      frameClasses: "border-blue-700/50 shadow-[0_0_10px_rgba(59,130,246,0.3)]",
      effects: null,
    };
  }

  // Cấp 30-49: Chiến Binh - Border xanh đậm, shadow tỏa nhiệt
  if (safeLevel >= 30) {
    config = {
      title: "CHIẾN BINH",
      textColor: "text-blue-200",
      badgeColor: "bg-gradient-to-br from-blue-700 to-indigo-800",
      frameClasses: "border-blue-600 shadow-[0_0_15px_rgba(37,99,235,0.5)]",
      effects: null,
    };
  }

  // Cấp 50-69: Tinh Anh (Lửa Tím)
  if (safeLevel >= 50) {
    config = {
      title: "TINH ANH",
      textColor: "text-purple-300",
      badgeColor: "bg-gradient-to-r from-purple-700 to-pink-700",
      frameClasses: "border-purple-600/50",
      effects: (
        // Hiệu ứng hào quang tím tỏa ra
        <motion.div
          key="purple-aura"
          animate={{ scale: [1, 1.1, 1], opacity: [0.5, 0.8, 0.5] }}
          transition={{ repeat: Infinity, duration: 3 }}
          className="absolute -inset-1 rounded-full bg-purple-500/20 blur-lg"
        />
      ),
    };
  }

  // Cấp 70-99: Huyền Thoại (Hào Quang Vàng)
  if (safeLevel >= 70) {
    config = {
      title: "HUYỀN THOẠI",
      textColor: "text-yellow-100",
      badgeColor: "bg-gradient-to-r from-yellow-500 via-amber-600 to-red-600",
      frameClasses: "border-amber-400/80 shadow-[0_0_20px_rgba(251,191,36,0.7)]",
      effects: (
        // Hiệu ứng "tia sét" vàng chạy quanh
        <motion.div
          key="gold-lightning"
          animate={{ rotate: 360 }}
          transition={{ repeat: Infinity, duration: 5, ease: "linear" }}
          className="absolute -inset-2 rounded-full border-2 border-dashed border-amber-300/60 blur-[1px]"
        />
      ),
    };
  }

  // Cấp 100+: Thủy Thần (Hiệu ứng Dòng chảy Cyan)
  if (safeLevel >= 100) {
    config = {
      title: "THỦY THẦN",
      textColor: "text-cyan-100",
      badgeColor: "bg-gradient-to-r from-cyan-400 via-blue-500 to-indigo-600",
      frameClasses: "border-cyan-300 shadow-[0_0_25px_rgba(34,211,238,0.9)]",
      effects: (
        // Hiệu ứng "dòng nước" xoáy quanh Avatar
        <div key="water-god-aura" className="absolute inset-0 pointer-events-none">
          <motion.div
            key="water-ring-1"
            animate={{ rotate: [0, -360] }}
            transition={{ repeat: Infinity, duration: 8, ease: "linear" }}
            className="absolute -inset-3 rounded-full border-2 border-cyan-400/60 blur-[2px]"
          />
          <motion.div
            key="water-ring-2"
            animate={{ scale: [1, 1.1, 1], rotate: 360 }}
            transition={{ repeat: Infinity, duration: 4, ease: "easeInOut" }}
            className="absolute -inset-2 rounded-full border border-blue-500/80 blur-[3px]"
          />
          <motion.div
            key="water-glow"
            animate={{ opacity: [0.4, 0.8, 0.4] }}
            transition={{ repeat: Infinity, duration: 2 }}
            className="absolute -inset-1.5 rounded-full bg-cyan-400/20 blur-xl"
          />
        </div>
      ),
    };
  }

  return config;
};

const sizeClasses = {
  sm: "w-12 h-12",
  md: "w-20 h-20",
  lg: "w-24 h-24",
  xl: "w-32 h-32",
};

const imageSizeClasses = {
  sm: "w-full h-full",
  md: "w-full h-full",
  lg: "w-full h-full",
  xl: "w-full h-full",
};

// Component chính
export default function AvatarFrame({ level, avatarUrl, size = 'md', showBadge = true, nickname }: AvatarFrameProps) {
  const { frameClasses, badgeColor, textColor, effects } = getFrameEffects(level);
  const currentSize = sizeClasses[size];
  const imageSize = imageSizeClasses[size];

  return (
    <div className={`relative ${currentSize} flex items-center justify-center`}>
      {/* 1. Hiệu ứng động bọc ngoài cùng (Chỉ có ở Rank cao) */}
      <AnimatePresence>
        {effects && React.cloneElement(effects as React.ReactElement, { key: "avatar-effects-wrapper" })}
      </AnimatePresence>

      {/* 2. Khung chính chứa Avatar */}
      <div className={`relative w-full h-full rounded-full p-[3px] bg-slate-950 z-10 ${frameClasses} transition-all flex items-center justify-center overflow-hidden`}>
        {avatarUrl ? (
          <img src={avatarUrl} alt="avatar" className="rounded-full object-cover w-full h-full" />
        ) : (
          <span className="font-black text-cyan-400" style={{ fontSize: size === 'sm' ? '1.25rem' : size === 'md' ? '1.75rem' : '2.5rem' }}>
            {(nickname || 'U').charAt(0).toUpperCase()}
          </span>
        )}
        
        {/* 3. Badge hiển thị số Level và Danh hiệu */}
        {showBadge && (
          <motion.div 
            initial={{ y: 5, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            className={`absolute -bottom-1 -right-1 ${badgeColor} rounded-full px-2 py-0.5 border border-white/20 z-20 shadow-md flex items-center gap-1`}
          >
            {level >= 70 && <Sparkles size={10} className="text-white animate-pulse" />}
            <span className="text-white font-black text-[10px] tracking-tighter">
              {level}
            </span >
            {level >= 30 && (
                <span className={`${textColor} text-[9px] font-bold`}>|</span>
            )}
             {level >= 30 && (
                 <span className={`${textColor} text-[9px] font-bold uppercase`}>{getRankTitle(level)}</span>
             )}
          </motion.div>
        )}
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';
import { Medal, Droplet, Target, Anchor, Beer, Moon, Trophy, CircleDashed, Star, Award, Flame, Zap } from 'lucide-react';
import { toast } from 'sonner';
// @ts-ignore
import confetti from 'canvas-confetti';

interface Badge {
  id: string;
  name: string;
  icon: string;
  rarity: string;
  description: string;
}

const iconMap: Record<string, React.ElementType> = {
  'droplet': Droplet,
  'ferris-wheel': Target, // Map ferris-wheel sang Target
  'target': Target,
  'anchor': Anchor,
  'beer': Beer,
  'moon': Moon,
  'trophy': Trophy,
  'circle-dashed': CircleDashed,
  'star': Star,
  'award': Award,
  'flame': Flame,
  'zap': Zap
};

export default function BadgesGrid({ userId }: { userId: string }) {
  const [badges, setBadges] = useState<Badge[]>([]);
  const [unlockedBadgeIds, setUnlockedBadgeIds] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(true);
  const [showAllBadges, setShowAllBadges] = useState(false);

  useEffect(() => {
    const fetchBadges = async () => {
      if (!userId || userId === 'undefined') return;
      setLoading(true);
      try {
        const [badgesRes, userBadgesRes] = await Promise.all([
          supabase.from('badges').select('*').order('rarity', { ascending: false }),
          supabase.from('user_badges').select('badge_id').eq('user_id', userId)
        ]);

        if (badgesRes.error) throw badgesRes.error;
        if (userBadgesRes.error) throw userBadgesRes.error;

        setBadges(badgesRes.data || []);
        setUnlockedBadgeIds(new Set((userBadgesRes.data || []).map((ub: any) => ub.badge_id)));
      } catch (error: any) {
        console.error("Error fetching badges:", error);
        toast.error("Không thể tải danh sách huy hiệu");
      } finally {
        setLoading(false);
      }
    };

    fetchBadges();

    // Lắng nghe Realtime từ Supabase khi có huy hiệu mới được chèn vào
    const channel = supabase
      .channel('badges_realtime')
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'user_badges', filter: `user_id=eq.${userId}` },
        (payload: any) => {
          const newBadgeId = payload.new.badge_id;
          
          // Tự động cập nhật UI: Chuyển huy hiệu sang trạng thái mở khóa
          setUnlockedBadgeIds(prev => new Set(prev).add(newBadgeId));
          
          // Kích hoạt hiệu ứng Confetti
          confetti({
            particleCount: 150,
            spread: 80,
            origin: { y: 0.6 },
            zIndex: 9999,
            colors: ['#06b6d4', '#f59e0b', '#10b981', '#a855f7'] // Cyan, Amber, Emerald, Purple
          });

          toast.success("Tuyệt vời! Bạn vừa mở khóa một Huy hiệu mới!", { icon: '🎉' });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId]);

  if (loading) return null;
  if (badges.length === 0) return null;

  // Phân bổ màu sắc dựa trên Rarity
  const getRarityStyles = (rarity: string, isUnlocked: boolean) => {
    if (!isUnlocked) return 'bg-slate-900/60 backdrop-blur-sm border-slate-800 text-slate-500 grayscale opacity-50';

    const r = rarity.toLowerCase();
    if (r === 'legendary') return 'bg-gradient-to-br from-cyan-500/20 to-blue-500/10 border-cyan-500/40 text-cyan-300 shadow-[0_0_15px_rgba(6,182,212,0.2)]';
    if (r === 'epic') return 'bg-gradient-to-br from-yellow-500/20 to-amber-500/10 border-yellow-500/40 text-yellow-400 shadow-[0_0_15px_rgba(234,179,8,0.2)]';
    if (r === 'rare') return 'bg-slate-300/20 border-slate-400/40 text-slate-300';
    if (r === 'animated') return 'bg-gradient-to-br from-purple-500/20 to-pink-500/10 border-purple-500/40 text-purple-400 shadow-[0_0_15px_rgba(147,51,234,0.2)]';
    return 'bg-orange-500/20 border-orange-500/40 text-orange-400'; // common
  };

  // Chỉ hiển thị 3 badges đầu tiên ban đầu
  const displayedBadges = showAllBadges ? badges : badges.slice(0, 3);
  const hasMoreBadges = badges.length > 3;

  return (
    <div className="space-y-4">
      <div className="flex items-center px-2">
        <h2 className="text-xl font-bold text-slate-50 flex items-center gap-2">
          <Medal size={20} className="text-yellow-400" />
          Bộ sưu tập Huy hiệu
        </h2>
      </div>

      <div className="grid grid-cols-3 gap-3">
        {displayedBadges.map((badge, index) => {
          const isUnlocked = unlockedBadgeIds.has(badge.id);
          const rarityStyles = getRarityStyles(badge.rarity, isUnlocked);
          const Icon = badge.icon && iconMap[badge.icon.toLowerCase()] ? iconMap[badge.icon.toLowerCase()] : Trophy;
          // Kiểm tra xem icon có phải là một đường dẫn ảnh URL (từ Supabase Storage) hay không
          const isImageUrl = badge.icon && (badge.icon.startsWith('http') || badge.icon.startsWith('/'));

          return (
            <div key={badge.id} className={`flex flex-col items-center p-4 rounded-3xl border text-center transition-all duration-500 ${rarityStyles}`}>
              <div className="mb-3 drop-shadow-lg transform hover:scale-110 transition-transform">
                {isImageUrl ? (
                  <img
                    src={badge.icon}
                    alt={badge.name}
                    className="w-12 h-12 object-contain drop-shadow-[0_0_15px_rgba(255,255,255,0.2)] animate-[floating_3s_ease-in-out_infinite]"
                    style={{ animationDelay: `${index * 0.2}s` }}
                  />
                ) : (
                  <Icon size={32} />
                )}
              </div>
              <p className="font-black text-[10px] uppercase tracking-wider mb-1.5 w-full leading-tight">{badge.name}</p>
              <p className="text-[9px] opacity-80 line-clamp-2 leading-tight font-medium">{badge.description}</p>
            </div>
          );
        })}
      </div>

      {/* Text "Tất cả" mờ ở góc nếu có nhiều hơn 3 badges */}
      {hasMoreBadges && (
        <div className="flex justify-end mt-2 px-2">
          <button
            onClick={() => setShowAllBadges(!showAllBadges)}
            className="text-slate-400 hover:text-slate-300 text-xs font-medium opacity-60 hover:opacity-100 transition-all duration-200 active:scale-95"
          >
            {showAllBadges ? 'Ẩn bớt' : `Tất cả`}
          </button>
        </div>
      )}
    </div>
  );
}

