import React, { useEffect, useState } from 'react';
import { Lock } from 'lucide-react';
import { useBiometric } from '../hooks/useBiometric';
import { motion, AnimatePresence } from 'framer-motion';

export default function LockedScreen({ profile, onUnlock, onLogout }: any) {
  const { authenticateBiometric, isAuthenticating } = useBiometric();
  const [isUnlocked, setIsUnlocked] = useState(false);
  
  useEffect(() => { handleUnlock(); }, []); // Tự động bật popup sinh trắc học khi mount

  const handleUnlock = async () => {
    if (!profile?.id) return;
    const success = await authenticateBiometric(profile.id);
    if (success) {
      setIsUnlocked(true);
      setTimeout(() => {
        onUnlock();
      }, 300); // Chờ hiệu ứng fade out hoàn tất (300ms)
    }
  };

  return (
    <AnimatePresence>
      {!isUnlocked && (
        <motion.div 
          key="locked-screen"
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 1.05 }}
          transition={{ duration: 0.3 }}
          className="flex flex-col min-h-screen items-center justify-center bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white p-6 font-sans"
        >
          <div className="w-20 h-20 bg-cyan-500/20 rounded-full flex items-center justify-center mb-6 border border-cyan-500/30">
            <Lock size={32} className="text-cyan-400" />
          </div>
          <h2 className="text-2xl font-black mb-2">Đã khóa ứng dụng</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-8 text-center text-sm">DigiWell được bảo vệ bằng Sinh trắc học.<br/>Vui lòng xác thực để tiếp tục.</p>
          <button onClick={handleUnlock} disabled={isAuthenticating} className="w-full max-w-xs py-4 rounded-2xl bg-cyan-500 text-white dark:text-black font-bold mb-4 shadow-[0_0_20px_rgba(6,182,212,0.4)] disabled:opacity-50 active:scale-95 transition-all">
            {isAuthenticating ? 'Đang xác thực...' : 'Mở khóa bằng Sinh trắc học'}
          </button>
          <button onClick={onLogout} className="text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors text-sm font-medium">Đăng nhập bằng tài khoản khác</button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import React, { useState } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';
import { Activity, ArrowRight, ArrowLeft, Droplets, Loader2, User } from 'lucide-react';

import type { Profile } from '../models';
interface OnboardingModalProps {
  profile: Profile;
  onComplete: (weight: number, waterGoal: number, name: string) => void;
}

export default function OnboardingModal({ profile, onComplete }: OnboardingModalProps) {
  // Initialize with existing weight if available, otherwise empty
  const [step, setStep] = useState(1);
  const [name, setName] = useState<string>(profile?.nickname || '');
  const [weight, setWeight] = useState<string>(profile.weight ? String(profile.weight) : '');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const waterGoal = weight ? Math.round(Number(weight) * 30) : 0; // 30ml/kg/day

  const handleNextStep = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) {
      toast.error('Vui lòng nhập tên của bạn!');
      return;
    }
    setStep(2);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const numWeight = Number(weight);
    if (!numWeight || numWeight <= 0 || numWeight > 300) {
      toast.error('Vui lòng nhập cân nặng hợp lệ!');
      return;
    }

    setIsSubmitting(true);
    try {
      const { error } = await supabase
        .from('profiles')
        .update({ nickname: name.trim(), weight: numWeight, water_goal: waterGoal, onboarding_completed: true })
        .eq('id', profile.id);

      if (error) throw error;
      
      toast.success('Đã cập nhật mục tiêu của bạn!');
      onComplete(numWeight, waterGoal, name.trim());
    } catch (error: any) {
      toast.error(error.message || 'Lỗi cập nhật hồ sơ!');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md" />
      <div className="relative w-full max-w-sm bg-slate-900 border border-cyan-500/30 rounded-[2rem] p-8 shadow-[0_0_40px_rgba(6,182,212,0.15)] animate-in zoom-in-95 overflow-hidden">
        <div className="absolute -top-20 -right-20 w-40 h-40 bg-cyan-500/20 blur-[50px] rounded-full pointer-events-none" />
        <div className="absolute -bottom-20 -left-20 w-40 h-40 bg-purple-500/20 blur-[50px] rounded-full pointer-events-none" />
        
        <div className="relative z-10">
          {step === 1 && (
            <div className="animate-in fade-in slide-in-from-right-4 duration-500">
              <div className="w-16 h-16 bg-cyan-500/10 border border-cyan-500/20 rounded-2xl flex items-center justify-center mb-6 mx-auto shadow-inner">
                <User size={32} className="text-cyan-400" />
              </div>
              
              <h2 className="text-2xl font-black text-white text-center mb-2 tracking-tight">Xin chào! Bạn tên là gì?</h2>
              <p className="text-sm text-slate-400 text-center mb-8 leading-relaxed">
                Hãy cho hệ thống biết cách xưng hô với bạn nhé.
              </p>

              <form onSubmit={handleNextStep} className="space-y-6">
                <div>
                  <div className="relative flex items-center justify-center">
                    <input 
                      type="text" 
                      value={name}
                      onChange={e => setName(e.target.value)}
                      placeholder="Tên của bạn..."
                      className="w-full bg-slate-800/50 border-2 border-slate-700 rounded-xl py-4 px-4 text-center text-lg font-bold text-white focus:border-cyan-500 focus:ring-0 outline-none transition-all"
                      autoFocus
                    />
                  </div>
                </div>

                <button 
                  type="submit" 
                  disabled={!name.trim()}
                  className="w-full py-4 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-500 text-white font-bold text-lg flex items-center justify-center gap-2 active:scale-95 transition-all shadow-[0_0_20px_rgba(6,182,212,0.4)] disabled:opacity-50 disabled:shadow-none hover:shadow-[0_0_30px_rgba(6,182,212,0.6)]"
                >
                  Tiếp tục <ArrowRight size={20} />
                </button>
              </form>
            </div>
          )}

          {step === 2 && (
            <div className="animate-in fade-in slide-in-from-right-4 duration-500">
              <button onClick={() => setStep(1)} className="absolute -top-4 -left-4 flex items-center gap-1 text-slate-400 hover:text-white transition-colors text-sm font-medium p-2">
                <ArrowLeft size={16} /> Quay lại
              </button>

              <div className="w-16 h-16 bg-cyan-500/10 border border-cyan-500/20 rounded-2xl flex items-center justify-center mb-6 mx-auto shadow-inner mt-6">
                <Activity size={32} className="text-cyan-400" />
              </div>
              
              <h2 className="text-2xl font-black text-white text-center mb-2 tracking-tight">Chào {name}! Bạn nặng bao nhiêu kg?</h2>
              <p className="text-sm text-slate-400 text-center mb-8 leading-relaxed">
                Hãy cho hệ thống biết cân nặng của bạn để AI tính toán lượng nước lý tưởng mỗi ngày nhé.
              </p>

              <form onSubmit={handleSubmit} className="space-y-6">
                <div>
                  <div className="relative flex items-center justify-center">
                    <input 
                      type="number" 
                      value={weight}
                      onChange={e => setWeight(e.target.value)}
                      placeholder="60"
                      className="w-32 bg-slate-800/50 border-2 border-slate-700 rounded-2xl py-3 text-center text-3xl font-black text-white focus:border-cyan-500 focus:ring-0 outline-none transition-all"
                      disabled={isSubmitting}
                      autoFocus
                    />
                    <span className="absolute right-6 text-slate-500 font-bold">kg</span>
                  </div>
                </div>

                <div className="bg-cyan-500/10 border border-cyan-500/20 rounded-2xl p-4 flex items-center justify-center gap-3">
                  <Droplets className="text-cyan-400" size={24} />
                  <div>
                    <p className="text-[10px] uppercase tracking-widest font-bold text-slate-400">Mục tiêu của bạn</p>
                    <p className="text-xl font-black text-cyan-300">{waterGoal} <span className="text-sm text-cyan-500/70">ml/ngày</span></p>
                  </div>
                </div>

                <button 
                  type="submit" 
                  disabled={isSubmitting || !weight}
                  className="w-full py-4 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-500 text-white font-bold text-lg flex items-center justify-center gap-2 active:scale-95 transition-all shadow-[0_0_20px_rgba(6,182,212,0.4)] disabled:opacity-50 disabled:shadow-none hover:shadow-[0_0_30px_rgba(6,182,212,0.6)]"
                >
                  {isSubmitting ? <Loader2 size={20} className="animate-spin" /> : <>Bắt đầu hành trình <ArrowRight size={20} /></>}
                </button>
              </form>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { motion, AnimatePresence, type Variants } from 'framer-motion';
import { Gift, Zap, CheckCircle2, Loader2, Sparkles, Flame, Star, Info, Volume2, Award } from 'lucide-react';

import type { UserQuest } from '../config/questConfig';
import { playSound } from '../lib/audio';
import { resolveQuestProgress } from '../lib/questProgress';

interface QuestCardProps {
  userQuest: UserQuest;
  onClaim: (id: string) => void | Promise<void>;
  isClaiming?: boolean;
  streak?: number;
  waterToday?: number;
  logCount?: number;
  userLevel?: number;
}

const rarityStyle: Record<string, { border: string; bg: string; shadow: string }> = {
  common: {
    border: 'border-slate-700',
    bg: 'bg-slate-900/80',
    shadow: '',
  },
  rare: {
    border: 'border-cyan-500/60',
    bg: 'bg-slate-900/80',
    shadow: 'shadow-[0_0_15px_rgba(6,182,212,0.15)]',
  },
  epic: {
    border: 'border-purple-500/60',
    bg: 'bg-slate-900/80',
    shadow: 'shadow-[0_0_20px_rgba(168,85,247,0.2)]',
  },
  legendary: {
    border: 'border-yellow-400/80',
    bg: 'bg-gradient-to-br from-yellow-500/10 via-amber-500/10 to-transparent',
    shadow: 'shadow-[0_0_30px_rgba(245,158,11,0.25)]',
  },
};

// 💥 BURST VARIANTS
const burstVariants: Variants = {
  hidden: { scale: 0, opacity: 0 },
  show: {
    scale: [0, 1.5, 1.2, 0],
    opacity: [0, 1, 0.8, 0],
    transition: { duration: 0.8, ease: "easeOut" },
  },
};

export const QuestCard: React.FC<QuestCardProps> = ({ userQuest, onClaim, isClaiming = false, streak = 0, waterToday, logCount, userLevel }) => {
  const [showBurst, setShowBurst] = useState(false);
  const [floatingText, setFloatingText] = useState<string | null>(null);
  const [showBreakdown, setShowBreakdown] = useState(false);

  const isClaimed = Boolean(userQuest.claimed_at);

  // 🧠 DATA ENGINE
  const baseExp = userQuest.quest.reward_exp;
  const finalExp = baseExp;
  const baseWp = userQuest.quest.reward_coins;
  const finalWp = baseWp;

  const rarity = userQuest.quest.rarity || 'common';

  const style = rarityStyle[rarity];

  // ⚡ COMBO MULTIPLIER & EVOLUTION STATE
  const multiplier = baseExp > 0 ? (finalExp / baseExp).toFixed(1) : "1.0";
  const numMultiplier = parseFloat(multiplier);
  
  let evoState = 'normal';
  if (numMultiplier >= 3.0) evoState = 'hyper';
  else if (numMultiplier >= 1.5) evoState = 'boosted';

  // HACK: Đồng bộ Realtime từ Frontend thay vì đợi Database (Khắc phục độ trễ)
  const actualProgress = useMemo(() => {
    const resolved = resolveQuestProgress(userQuest.quest, {
      waterToday,
      logCountToday: logCount,
      streak,
      level: userLevel,
    });

    return Math.max(Number(userQuest.progress || 0), resolved.progress);
  }, [userQuest.progress, userQuest.quest, waterToday, logCount, streak, userLevel]);

  const progressPercent = useMemo(() => {
    if (!userQuest.quest.condition_value) return 0;
    return Math.min((actualProgress / userQuest.quest.condition_value) * 100, 100);
  }, [actualProgress, userQuest.quest.condition_value]);

  const isCompleted = userQuest.status === 'completed' || actualProgress >= Number(userQuest.quest.condition_value || 0);
  const canClaim = isCompleted && !isClaimed && !isClaiming;

  const handleClaim = () => {
    playSound(evoState === 'hyper' ? 'hyper' : 'claim');
    setShowBurst(true);
    setFloatingText(`+${finalExp} EXP`);

    setTimeout(() => setFloatingText(null), 1000);
    setTimeout(() => setShowBurst(false), 900);

    onClaim(userQuest.id);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={!isClaimed ? { scale: 1.02 } : undefined}
      whileTap={!isClaimed ? { scale: 0.99 } : undefined}
      onMouseEnter={() => !isClaimed && playSound('hover')}
      className={`relative overflow-hidden p-5 rounded-3xl border transition-all duration-300 backdrop-blur-sm ${
        isClaimed
          ? 'bg-slate-800/40 border-slate-700/40 opacity-60 grayscale-[40%]'
          : isCompleted
            ? 'bg-gradient-to-br from-yellow-500/10 via-amber-500/10 to-transparent border-amber-400/50 shadow-[0_0_30px_rgba(245,158,11,0.15)]'
            : `${style.bg} ${style.border} ${style.shadow}`
      }`}
    >
      {evoState === 'hyper' && !isClaimed && (
        <div className="absolute inset-0 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] opacity-30 animate-[spin_60s_linear_infinite]" />
      )}

      {/* 🌟 LEGENDARY SHIMMER */}
      {rarity === 'legendary' && !isClaimed && (
        <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_top,rgba(255,215,0,0.15),transparent_60%)] animate-pulse" />
      )}

      {/* 💥 BURST FX */}
      <AnimatePresence>
        {showBurst && (
          <motion.div
            key="burst-fx"
            variants={burstVariants}
            initial="hidden"
            animate="show"
            exit="hidden"
            className="absolute inset-0 flex items-center justify-center pointer-events-none z-20"
          >
            <div className={`w-32 h-32 rounded-full blur-2xl opacity-80 ${evoState === 'hyper' ? 'bg-red-500' : 'bg-yellow-400'}`} />
          </motion.div>
        )}
      </AnimatePresence>

      {/* 🎁 FLOATING REWARD DAMAGE */}
      <AnimatePresence>
        {floatingText && (
          <motion.div
            key="floating-text"
            initial={{ opacity: 0, y: 10, scale: 0.5 }}
            animate={{ opacity: 1, y: -40, scale: 1.5 }}
            exit={{ opacity: 0 }}
            className={`absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 font-black text-3xl pointer-events-none z-30 
              ${evoState === 'hyper' ? 'text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.8)]' : 'text-amber-400 drop-shadow-[0_0_10px_rgba(251,191,36,0.8)]'}
            `}
          >
            {floatingText}
            {evoState === 'hyper' && <span className="block text-[10px] text-center text-white mt-1 uppercase tracking-widest">CRITICAL HIT!</span>}
          </motion.div>
        )}
      </AnimatePresence>

      {/* HEADER */}
      <div className="flex justify-between items-start gap-4 relative z-10">
        <div className="pr-3">
          <div className="flex items-center gap-2 mb-1">
            <h3 className={`font-bold text-base ${isClaimed ? 'text-slate-400' : 'text-white'}`}>
              {userQuest.quest.title}
            </h3>
            {(userQuest.quest as any).type === 'weekly' && (
              <span className="px-2 py-0.5 rounded text-[8px] font-black bg-purple-500/20 text-purple-400 uppercase tracking-widest border border-purple-500/30">Tuần</span>
            )}
            {(userQuest.quest as any).type === 'daily' && (
              <span className="px-2 py-0.5 rounded text-[8px] font-black bg-cyan-500/20 text-cyan-400 uppercase tracking-widest border border-cyan-500/30">Ngày</span>
            )}
            {(userQuest.quest as any).type === 'level' && (
              <span className="px-2 py-0.5 rounded text-[8px] font-black bg-amber-500/20 text-amber-400 uppercase tracking-widest border border-amber-500/30">Vĩnh viễn</span>
            )}
          </div>
          <p className="text-slate-400 text-xs mt-1">
            {userQuest.quest.description}
          </p>

          {/* ⚡ COMBO / STREAK UI */}
          {streak > 0 && !isClaimed && (
            <div className="inline-flex items-center gap-1.5 bg-gradient-to-r from-orange-500/20 to-red-500/10 px-2.5 py-1 rounded-md border border-orange-500/30 mt-3 shadow-inner">
              <Flame size={14} className="text-orange-500 animate-pulse" />
              <span className="text-[10px] font-black text-orange-400 tracking-wide">
                STREAK {streak} <span className="text-red-400">🔥</span>
              </span>
            </div>
          )}
        </div>

        {/* 🏆 REWARD ZONE + BREAKDOWN TOOLTIP */}
        <div 
          className="text-right shrink-0 relative cursor-help"
          onMouseEnter={() => { setShowBreakdown(true); playSound('hover'); }}
          onMouseLeave={() => setShowBreakdown(false)}
        >
          {/* Main Reward Display */}
          <div className="flex flex-col items-end gap-0.5">
            {evoState !== 'normal' && !isClaimed && (
              <span className="text-[10px] text-slate-500 line-through font-mono">
                {baseExp} EXP
              </span>
            )}
            <div className={`flex items-center justify-end gap-1 font-black text-sm transition-colors
              ${isClaimed ? 'text-slate-500' : evoState === 'hyper' ? 'text-red-400 drop-shadow-[0_0_8px_rgba(239,68,68,0.6)]' : evoState === 'boosted' ? 'text-amber-400' : 'text-yellow-400'}
            `}>
              {evoState !== 'normal' && !isClaimed ? <Star size={14} className="fill-current" /> : <Gift size={14} />} 
              +{finalExp} EXP
            </div>
          </div>
          <div className="flex flex-col items-end gap-0.5 mt-1">
             {evoState !== 'normal' && !isClaimed && (
              <span className="text-[9px] text-slate-500 line-through font-mono">
                {baseWp} WP
              </span>
            )}
            <div className={`flex items-center justify-end gap-1 text-xs font-bold ${isClaimed ? 'text-slate-600' : 'text-cyan-400'}`}>
              <Zap size={12} /> +{finalWp} WP
            </div>
          </div>
          {(userQuest.quest as any).reward_badge_id && (
            <div className={`flex items-center justify-end gap-1 text-[10px] font-bold mt-1 ${isClaimed ? 'text-slate-600' : 'text-fuchsia-400'}`}>
              <Award size={12} /> +Huy hiệu
            </div>
          )}

          {/* 🔍 THE BREAKDOWN PREVIEW (Tooltip) */}
          <AnimatePresence>
            {showBreakdown && !isClaimed && (
              <motion.div
                key="breakdown-tooltip"
                initial={{ opacity: 0, y: 10, scale: 0.9 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: 5, scale: 0.95 }}
                className="absolute top-full right-0 mt-3 w-48 p-3 rounded-xl bg-slate-900 border border-slate-700 shadow-[0_10px_30px_rgba(0,0,0,0.8)] z-50 pointer-events-none"
              >
                <div className="flex items-center gap-1.5 border-b border-slate-800 pb-2 mb-2">
                  <Info size={12} className="text-cyan-400" />
                  <span className="text-[10px] font-bold text-slate-300 uppercase tracking-wider">Chi tiết lợi nhuận</span>
                </div>
                <div className="space-y-1.5 text-[10px] font-mono">
                  <div className="flex justify-between text-slate-400">
                    <span>Base EXP</span>
                    <span>{baseExp}</span>
                  </div>
                  {rarity !== 'common' && (
                    <div className="flex justify-between text-purple-400">
                      <span>Rarity Bonus</span>
                      <span>x{rarity === 'epic' ? '2.5' : rarity === 'legendary' ? '5.0' : '1.5'}</span>
                    </div>
                  )}
                  {streak > 0 && (
                    <div className="flex justify-between text-orange-400">
                      <span>Streak Buff</span>
                      <span>+{Math.min(streak * 5, 50)}%</span>
                    </div>
                  )}
                </div>
                <div className="mt-2 pt-2 border-t border-slate-800 flex justify-between items-center">
                  <span className="text-[10px] font-bold text-slate-500">HỆ SỐ TỔNG</span>
                  <span className="text-xs font-black text-amber-400">x{numMultiplier}</span>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* RARITY BADGE */}
      {!isClaimed && (
        <div className="absolute top-3 right-3 text-[9px] px-2 py-1 rounded-full bg-black/60 border border-white/10 uppercase tracking-widest text-slate-300 font-bold z-10 flex items-center gap-1">
          {rarity}
          {evoState === 'hyper' && <span className="text-red-500 animate-pulse">✦</span>}
        </div>
      )}

      {/* PROGRESS */}
      <div className="mt-5 space-y-2 relative z-10">
        <div className="flex justify-between text-[10px] font-mono">
          <span className="text-slate-500 uppercase font-bold tracking-wider">Tiến độ</span>
          <span className={isCompleted ? 'text-amber-400 font-bold' : 'text-slate-300'}>
            {actualProgress.toLocaleString()} / {userQuest.quest.condition_value.toLocaleString()}
          </span>
        </div>

        <div className="h-2 w-full bg-black/40 rounded-full overflow-hidden border border-white/10 relative">
          <motion.div
            initial={{ width: 0 }}
            animate={{ width: `${progressPercent}%` }}
            transition={{ duration: 0.8, ease: "easeOut" }}
            className={`h-full absolute left-0 top-0 ${
              isCompleted
                ? evoState === 'hyper' 
                  ? 'bg-gradient-to-r from-orange-500 via-red-500 to-purple-600' // Thanh máu Hyper
                  : 'bg-gradient-to-r from-yellow-400 via-amber-400 to-yellow-500'
                : 'bg-cyan-500'
            }`}
          >
            {isCompleted && <div className="absolute inset-0 bg-white/20 animate-[shimmer_1s_infinite] -skew-x-12" />}
          </motion.div>
        </div>
      </div>

      {/* FOOTER */}
      <div className="mt-5 pt-4 border-t border-white/10 flex justify-end relative z-10">
        {isClaimed ? (
          <div className="flex items-center gap-2 text-emerald-500 font-bold text-sm">

          </div>
        ) : (
          <motion.button
            whileHover={canClaim ? { scale: 1.04 } : undefined}
            whileTap={canClaim ? { scale: 0.96 } : undefined}
            onClick={handleClaim}
            onMouseEnter={() => canClaim && playSound('hover')}
            disabled={!canClaim || isClaiming}
            className={`px-6 py-2.5 text-xs font-black rounded-xl min-w-[130px]
              flex items-center justify-center gap-2 transition-all relative overflow-hidden group
              ${
                canClaim
                  ? evoState === 'hyper'
                    ? 'bg-gradient-to-r from-red-600 to-orange-500 text-white shadow-[0_0_20px_rgba(239,68,68,0.5)] border border-red-400/50' // Nút đỏ rực cho Hyper
                    : 'bg-amber-500 text-black shadow-[0_0_15px_rgba(245,158,11,0.4)] hover:bg-amber-400'
                  : 'bg-slate-800 text-slate-500 border border-slate-700 cursor-not-allowed'
              }
            `}
          >
            {/* Shimmer Light on Hover */}
            {canClaim && !isClaiming && (
              <div className="absolute inset-0 -translate-x-full group-hover:animate-[shimmer_1.5s_infinite] bg-gradient-to-r from-transparent via-white/30 to-transparent" />
            )}
            
            {isClaiming ? (
              <>
                <Loader2 size={16} className="animate-spin" />
                Đang nén khí...
              </>
            ) : canClaim ? (
              <>
                {evoState === 'hyper' ? <Volume2 size={14} className="animate-pulse" /> : <Sparkles size={14} />}
                {evoState === 'hyper' ? 'NHẬN SIÊU BUFF' : 'Nhận Thưởng'}
              </>
            ) : (
              'Chưa Đạt'
            )}
          </motion.button>
        )}
      </div>
    </motion.div>
  );
};

