                        className={`absolute bottom-0 w-full ${activeBattle.challenger_id === profile?.id ? 'bg-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.8)]' : 'bg-rose-500 shadow-[0_0_15px_rgba(225,29,72,0.8)]'}`} 
