import { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { Capacitor } from '@capacitor/core';
import { App as CapacitorApp } from '@capacitor/app';
import { Browser } from '@capacitor/browser';
import { useWeatherSync } from './useWeatherSync';
import {
  CALENDAR_OAUTH_PENDING_KEY,
  CALENDAR_TOKEN_UPDATED_EVENT,
  GOOGLE_PROVIDER_TOKEN_KEY,
  useCalendarSync,
} from './useCalendarSync';
import { useDeviceHealth } from './useDeviceHealth';

export function useAppSystem() {
  const [view, setView] = useState<'welcome' | 'login' | 'register' | 'app' | 'locked'>('welcome');
  const [profile, setProfile] = useState<any>(null);
  const [loginPrefill, setLoginPrefill] = useState('');

  const { isWeatherSynced, setIsWeatherSynced, weatherData, syncWeather } = useWeatherSync();
  const { isCalendarSynced, setIsCalendarSynced, calendarEvents, syncCalendar } = useCalendarSync();
  const { isWatchConnected, toggleHealthConnection, watchData, isLoading: isHealthLoading } = useDeviceHealth(profile?.id);

  const loadProfileForCurrentUser = async () => {
    try {
      const { data: sessionRes, error: sessionErr } = await supabase!.auth.getSession();
      if (sessionErr || !sessionRes.session?.user.id) return null;
      const userId = sessionRes.session.user.id;
      
      const { data: p, error: pErr } = await supabase!.from('profiles').select('*').eq('id', userId).single();
      if (pErr || !p) return null;

      // Check if last_water_date is not today, reset water_today to 0
      const today = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}-${String(new Date().getDate()).padStart(2, '0')}`;
      console.log('[useAppSystem] Loading profile:', { total_exp: p.total_exp, level: p.level, water_today: p.water_today, last_water_date: p.last_water_date, today });
      if (p.last_water_date !== today) {
        console.log('[useAppSystem] Resetting water_today for new day');
        await supabase!.from('profiles').update({
          water_today: 0,
          last_water_date: today
        }).eq('id', userId);
        p.water_today = 0;
        p.last_water_date = today;
      }

      return {
        id: p.id, nickname: p.nickname, password: '', gender: p.gender,
        age: p.age, height: p.height, weight: p.weight, activity: p.activity,
        climate: p.climate, goal: p.goal, wakeUp: p.wake_up, bedTime: p.bed_time,
        water_goal: p.water_goal, wp: p.wp, coins: p.coins, total_exp: p.total_exp, level: p.level,
        water_today: p.water_today, total_water: p.total_water,
        onboarding_completed: p.onboarding_completed
      };
    } catch { return null; }
  };

  useEffect(() => {
    if (Capacitor.isNativePlatform()) {
      const sub = CapacitorApp.addListener('appUrlOpen', async (event) => {
        if (
          event.url.includes('login-callback') ||
          event.url.includes('billing-return') ||
          event.url.includes('access_token') ||
          event.url.includes('code=')
        ) {
          Browser.close().catch(() => {});
          const urlStr = event.url;
          if (urlStr.includes('#') || urlStr.includes('?')) {
            const fragment = urlStr.substring(urlStr.indexOf(urlStr.includes('?') ? '?' : '#'));
            window.location.href = `${window.location.origin}${window.location.pathname}${fragment}`;
            
            setTimeout(async () => {
              const { data } = await supabase!.auth.getSession();
              if (data?.session) {
                setView('app');
              }
            }, 500);
          }
        }
      });
      return () => { sub.then(s => s.remove()); };
    }
  }, []);

  useEffect(() => {
    let isMounted = true;
    let timeoutId: ReturnType<typeof setTimeout>;
    
    const { data: sub } = supabase!.auth.onAuthStateChange(async (event: string, session: any) => {
      if (!isMounted) return;
      try {
        if (session) {
          if (session.provider_token) {
            localStorage.setItem(GOOGLE_PROVIDER_TOKEN_KEY, session.provider_token);
            window.dispatchEvent(new CustomEvent(CALENDAR_TOKEN_UPDATED_EVENT));
          }
          if (event === 'SIGNED_IN' || event === 'INITIAL_SESSION' || event === 'USER_UPDATED') {
            if (timeoutId) clearTimeout(timeoutId);
            timeoutId = setTimeout(async () => {
              let p = await loadProfileForCurrentUser();
              if (!p && session.user) {
                const defaultName = session.user.user_metadata?.full_name || session.user.email?.split('@')[0] || 'User';
                await supabase!.from('profiles').upsert([{ id: session.user.id, nickname: defaultName, gender: 'Nam', age: 20, height: 170, weight: 60, activity: 'active', climate: 'Nhiệt đới (Nóng)', goal: 'Sức khỏe tổng quát' }], { onConflict: 'id' });
                p = await loadProfileForCurrentUser();
              }
              if (p && isMounted) { 
                setProfile(p); 
                const isBiometricEnabled = localStorage.getItem('biometric_enabled') === 'true';
                setView(isBiometricEnabled ? 'locked' : 'app'); 
              }
            }, 500);
          }
        } else if (event === 'SIGNED_OUT' || !session) { 
          setProfile(null);
          localStorage.removeItem(GOOGLE_PROVIDER_TOKEN_KEY);
          localStorage.removeItem(CALENDAR_OAUTH_PENDING_KEY);
          window.dispatchEvent(new CustomEvent(CALENDAR_TOKEN_UPDATED_EVENT));
          setView('welcome');
        }
      } catch (error) { console.error(error); }
    });
    return () => { isMounted = false; if (timeoutId) clearTimeout(timeoutId); sub?.subscription.unsubscribe(); };
  }, []);

  const handleLogout = async () => { if (window.confirm("Xác nhận đăng xuất an toàn?")) { await supabase!.auth.signOut(); } };

  return { view, setView, profile, setProfile, loginPrefill, setLoginPrefill, handleLogout, isWeatherSynced, setIsWeatherSynced, weatherData, syncWeather, isCalendarSynced, setIsCalendarSynced, calendarEvents, syncCalendar, isWatchConnected, toggleHealthConnection, watchData, isHealthLoading };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';

export function useBattleArena(profile: any, isOpen: boolean, onSpendCoins: (amount: number) => Promise<boolean>) {
  const [activeBattle, setActiveBattle] = useState<any>(null);
  const [pendingInvites, setPendingInvites] = useState<any[]>([]);
  const [opponents, setOpponents] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [stakeAmount, setStakeAmount] = useState(100);

  const loadArenaData = useCallback(async () => {
    if (!profile?.id) return;
    setIsLoading(true);
    
    try {
      const { data: battles, error } = await supabase
        .from('hydration_battles')
        .select(`
          *,
          challenger:profiles!challenger_id(id, nickname, avatar_url, water_today, water_goal),
          opponent:profiles!opponent_id(id, nickname, avatar_url, water_today, water_goal)
        `)
        .or(`challenger_id.eq.${profile.id},opponent_id.eq.${profile.id}`)
        .order('created_at', { ascending: false });

      if (error) throw error;

      const today = new Date().toISOString().split('T')[0];
      let currentActive = battles?.find((b: any) => b.status === 'active');
      
      if (currentActive) {
        const battleDay = new Date(currentActive.created_at).toISOString().split('T')[0];
        if (battleDay < today) {
          const { data: result, error } = await supabase.rpc('resolve_stale_battle', {
            battle_id: currentActive.id
          });
          if (!error && result) {
            if (result.status === 'won') toast.success(`🎉 Trận hôm qua đã kết thúc. Bạn THẮNG và ẵm trọn ${result.reward} Vàng!`, { duration: 8000 });
            else if (result.status === 'draw') toast.info(`Trận đấu hôm qua HÒA. Đã hoàn trả ${result.reward} Vàng.`);
            else if (result.status === 'lost') toast.error(`Thua cuộc! Đối thủ đã uống nhiều hơn bạn vào hôm qua.`);
          }
          currentActive = null; 
        }
      }

      setActiveBattle(currentActive);
      setPendingInvites(battles?.filter((b: any) => b.status === 'pending' && b.opponent_id === profile.id) || []);

      if (!currentActive) {
        const { data: users } = await supabase.from('profiles').select('id, nickname, level, avatar_url').neq('id', profile.id).limit(10);
        setOpponents(users || []);
      }
    } catch (err) {
      console.error(err);
      toast.error('Lỗi tải dữ liệu Đấu trường');
    } finally {
      setIsLoading(false);
    }
  }, [profile]);

  useEffect(() => {
    if (isOpen) loadArenaData();
  }, [isOpen, loadArenaData]);

  const handleChallenge = async (opponentId: string) => {
    if (profile.coins < stakeAmount) return toast.error('Không đủ Vàng để cược!');
    const success = await onSpendCoins(stakeAmount);
    if (!success) return;

    const tid = toast.loading('Đang rải chiến thư...');
    try {
      await supabase.from('hydration_battles').insert({
        challenger_id: profile.id, opponent_id: opponentId, stake_coins: stakeAmount, status: 'pending'
      });
      toast.success('Đã gửi chiến thư!', { id: tid });
      loadArenaData();
    } catch (err) {
      toast.error('Lỗi gửi thách đấu', { id: tid });
    }
  };

  const handleAccept = async (battle: any) => {
    if (profile.coins < battle.stake_coins) return toast.error('Sếp không đủ Vàng để theo cược!');
    const success = await onSpendCoins(battle.stake_coins);
    if (!success) return;

    const tid = toast.loading('Đang lên đài...');
    try {
      await supabase.from('hydration_battles').update({ status: 'active' }).eq('id', battle.id);
      const otherPending = pendingInvites.filter((b: any) => b.id !== battle.id);
      for (const p of otherPending) {
        await supabase.from('hydration_battles').update({ status: 'declined' }).eq('id', p.id);
      }
      toast.success('🔥 Bắt đầu cuộc đua!', { id: tid });
      loadArenaData();
    } catch (err) {
      toast.error('Lỗi vào trận', { id: tid });
    }
  };

  return { activeBattle, pendingInvites, opponents, isLoading, stakeAmount, setStakeAmount, handleChallenge, handleAccept };
}

// ============================================================
// DigiWell — Biometric Authentication Hook
// NATIVE BIOMETRIC (Face ID / Touch ID) via Capacitor Plugin
// ============================================================

import { useState, useCallback } from 'react';
import { toast } from 'sonner';
import { Capacitor } from '@capacitor/core';
// @ts-ignore: Bỏ qua lỗi check type của TypeScript cho plugin này
import { NativeBiometric } from '@capgo/capacitor-native-biometric';

export function useBiometric() {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  const isBiometricSupported = useCallback(async (): Promise<boolean> => {
    if (!Capacitor.isNativePlatform()) return false;
    try {
      const result = await NativeBiometric.isAvailable();
      return result.isAvailable;
    } catch {
      return false;
    }
  }, []);

  const registerBiometric = useCallback(async (userId: string): Promise<boolean> => {
    setIsRegistering(true);
    try {
      if (!Capacitor.isNativePlatform()) {
        toast.error('Tính năng này chỉ hoạt động trên thiết bị di động thật!');
        return false;
      }

      // Kiểm tra thiết bị có hỗ trợ không
      const available = await NativeBiometric.isAvailable();
      if (!available.isAvailable) throw new Error('Thiết bị không hỗ trợ Sinh trắc học');

      // Quét mặt 1 lần để xác nhận chủ máy trước khi bật khóa
      await NativeBiometric.verifyIdentity({
        reason: "Xác nhận danh tính để bật Khóa ứng dụng",
        title: "Thiết lập bảo mật",
      });

      localStorage.setItem('biometric_enabled', 'true');
      toast.success('✅ Bật khóa sinh trắc học thành công!');
      return true;
    } catch (error: any) {
      toast.error('Thiết lập thất bại hoặc đã bị hủy.');
      return false;
    } finally {
      setIsRegistering(false);
    }
  }, []);

  const authenticateBiometric = useCallback(async (userId: string): Promise<boolean> => {
    setIsAuthenticating(true);
    try {
      if (!Capacitor.isNativePlatform()) return true; // Bypass trên web demo

      const isEnabled = localStorage.getItem('biometric_enabled') === 'true';
      if (!isEnabled) {
        toast.error('Bạn chưa bật tính năng khóa ứng dụng');
        return false;
      }

      await NativeBiometric.verifyIdentity({
        reason: "Quét khuôn mặt / Vân tay để mở khóa DigiWell",
        title: "Mở khóa DigiWell",
      });

      return true;
    } catch (error: any) {
      toast.error('Xác thực không thành công.');
      return false;
    } finally {
      setIsAuthenticating(false);
    }
  }, []);

  const disableBiometric = useCallback((userId: string) => {
    localStorage.removeItem('biometric_enabled');
    toast.info('🔒 Đã tắt đăng nhập sinh trắc học');
  }, []);

  const getBiometricStatus = useCallback((userId: string) => {
    const enabled = localStorage.getItem('biometric_enabled') === 'true';
    return { registered: enabled, enabled };
  }, []);

  return {
    isBiometricSupported,
    isRegistering,
    isAuthenticating,
    registerBiometric,
    authenticateBiometric,
    disableBiometric,
    getBiometricStatus,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';

export interface Challenge {
  id: string;
  type: 'time_limited' | 'milestone';
  slug: string;
  title: string;
  description: string;
  duration_days: number | null;
  target_value: number | null;
  reward_exp: number;
  reward_coins: number;
  min_rank: number;
  category: string;
  difficulty: 'easy' | 'normal' | 'hard' | 'elite' | 'mythic';
  premium_only: boolean;
}

export interface UserChallenge {
  id: string;
  challenge_id: string;
  status: string;
  current_value: number;
  days_completed: number;
  days_failed: number;
  joined_at: string;
}

export function useChallenges(userId: string) {
  const [challenges, setChallenges] = useState<Challenge[]>([]);
  const [userChallenges, setUserChallenges] = useState<UserChallenge[]>([]);
  const [loading, setLoading] = useState(true);
  const [joiningId, setJoiningId] = useState<string | null>(null);

  const fetchChallenges = useCallback(async () => {
    if (!userId || userId === 'undefined') return;

    // 1. Load từ Local Cache trước (Offline-First)
    try {
      const cachedC = localStorage.getItem(`digiwell_challenges_cache`);
      const cachedUC = localStorage.getItem(`digiwell_user_challenges_cache_${userId}`);
      if (cachedC && cachedUC) {
        setChallenges(JSON.parse(cachedC));
        setUserChallenges(JSON.parse(cachedUC));
        setLoading(false);
      } else {
        setLoading(true);
      }
    } catch(e) {}

    try {
      const [challengesRes, userChallengesRes] = await Promise.all([
        supabase.from('challenges').select('*').eq('is_active', true).order('sort_order', { ascending: true }),
        supabase.from('user_challenges').select('*').eq('user_id', userId).eq('status', 'joined')
      ]);

      if (challengesRes.error) throw challengesRes.error;
      if (userChallengesRes.error) throw userChallengesRes.error;

      const newChallenges = challengesRes.data || [];
      const newUserChallenges = userChallengesRes.data || [];

      setChallenges(newChallenges);
      setUserChallenges(newUserChallenges);

      // 2. Cập nhật lại Cache
      localStorage.setItem(`digiwell_challenges_cache`, JSON.stringify(newChallenges));
      localStorage.setItem(`digiwell_user_challenges_cache_${userId}`, JSON.stringify(newUserChallenges));
    } catch (error: any) {
      console.error("Error fetching challenges:", error);
      toast.error("Không thể tải danh sách thử thách");
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    fetchChallenges();
  }, [fetchChallenges]);

  const handleJoinChallenge = async (challenge: Challenge) => {
    setJoiningId(challenge.id);
    const toastId = toast.loading("Đang đăng ký tham gia...");

    try {
      const { error } = await supabase.from('user_challenges').insert({
        user_id: userId,
        challenge_id: challenge.id,
        status: 'joined',
        current_value: 0,
        days_completed: 0,
        days_failed: 0,
        milestones_reached: []
      });

      if (error) throw error;

      toast.success(`Đã tham gia: ${challenge.title}`, { id: toastId });

      const { data: updatedUserChallenges, error: refetchError } = await supabase
        .from('user_challenges')
        .select('*')
        .eq('user_id', userId)
        .eq('status', 'joined');

      if (refetchError) throw refetchError;
      setUserChallenges(updatedUserChallenges || []);

    } catch (error: any) {
      console.error("Error joining challenge:", error);
      toast.error("Lỗi khi tham gia thử thách. Vui lòng thử lại.", { id: toastId });
    } finally {
      setJoiningId(null);
    }
  };

  return { challenges, userChallenges, loading, joiningId, handleJoinChallenge };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';

export function useClubs(userId?: string) {
  const [myClub, setMyClub] = useState<any>(null);
  const [allClubs, setAllClubs] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [joining, setJoining] = useState(false);

  // =========================
  // LOAD DATA
  // =========================
  const fetchClubData = useCallback(async () => {
    if (!userId) {
      setMyClub(null);
      setAllClubs([]);
      return;
    }

    setLoading(true);

    try {
      // user current club
      const { data: memberData, error: memberError } = await supabase
        .from('club_members')
        .select(`
          role,
          club_id,
          clubs (
            id,
            name,
            description,
            avatar_url,
            owner_id,
            daily_goal,
            is_private,
            created_at
          )
        `)
        .eq('user_id', userId)
        .maybeSingle();

      if (memberError) throw memberError;

      const clubData = memberData?.clubs
        ? {
            ...memberData.clubs,
            role: memberData.role
          }
        : null;

      setMyClub(clubData);

      // all clubs
      const { data: clubsData, error: clubsError } = await supabase
        .from('clubs')
        .select(`
          *,
          club_members(count)
        `)
        .order('created_at', { ascending: false });

      if (clubsError) throw clubsError;

      const normalized =
        clubsData?.map((club: any) => ({
          ...club,
          member_count: club.club_members?.[0]?.count ?? 0
        })) || [];

      setAllClubs(normalized);
    } catch (error: any) {
      console.error('fetchClubData error:', error);
      toast.error('Không tải được dữ liệu club');
    } finally {
      setLoading(false);
    }
  }, [userId]);

  // =========================
  // JOIN CLUB
  // =========================
  const joinClub = useCallback(
    async (clubId: string) => {
      if (!userId || joining) return;

      try {
        setJoining(true);

        // leave current first
        await supabase
          .from('club_members')
          .delete()
          .eq('user_id', userId);

        const { error } = await supabase
          .from('club_members')
          .insert({
            user_id: userId,
            club_id: clubId,
            role: 'member'
          });

        if (error) throw error;

        toast.success('Đã tham gia câu lạc bộ');
        fetchClubData();
      } catch (error: any) {
        console.error(error);
        toast.error('Không thể tham gia club');
      } finally {
        setJoining(false);
      }
    },
    [userId, joining, fetchClubData]
  );

  // =========================
  // LEAVE CLUB
  // =========================
  const leaveClub = useCallback(async () => {
    if (!userId) return;

    try {
      const { error } = await supabase
        .from('club_members')
        .delete()
        .eq('user_id', userId);

      if (error) throw error;

      setMyClub(null);
      toast.success('Đã rời câu lạc bộ');
      fetchClubData();
    } catch (error) {
      toast.error('Không thể rời club');
    }
  }, [userId, fetchClubData]);

  // =========================
  // INITIAL LOAD + REALTIME
  // =========================
  useEffect(() => {
    if (!userId) return;

    fetchClubData();

    const channel = supabase
      .channel(`clubs-${userId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'club_members'
        },
        () => {
          fetchClubData();
        }
      )
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'clubs'
        },
        () => {
          fetchClubData();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId, fetchClubData]);

  return {
    myClub,
    allClubs,
    loading,
    joining,
    joinClub,
    leaveClub,
    refresh: fetchClubData
  };
}

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';

export function useComments(postId: string, currentUserId: string | undefined) {
  const [comments, setComments] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const fetchComments = useCallback(async () => {
    setIsLoading(true);
    const { data, error } = await supabase
      .from('social_post_comments')
      .select('*, author:profiles (nickname, avatar_url)')
      .eq('post_id', postId)
      .order('created_at', { ascending: true });
    if (!error && data) setComments(data);
    setIsLoading(false);
  }, [postId]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/exhaustive-deps
    fetchComments();
  }, [fetchComments]);

  const addComment = async (content: string) => {
    if (!currentUserId || !content.trim()) return;
    const tempId = `temp-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
    const newComment = { id: tempId, post_id: postId, user_id: currentUserId, content, created_at: new Date().toISOString(), author: { nickname: 'Bạn' } };
    
    setComments(prev => [...prev, newComment]); // Optimistic
    
    const { data, error } = await supabase.from('social_post_comments').insert({ post_id: postId, user_id: currentUserId, content }).select('*, author:profiles (nickname, avatar_url)').single();
    
    if (error) {
      setComments(prev => prev.filter(c => c.id !== tempId));
      toast.error('Gửi bình luận thất bại');
    } else if (data) {
      setComments(prev => prev.map(c => c.id === tempId ? data : c));
    }
  };

  const deleteComment = async (id: string) => {
    const prev = [...comments];
    setComments(prev.filter(c => c.id !== id));
    const { error } = await supabase.from('social_post_comments').delete().eq('id', id);
    if (error) { setComments(prev); toast.error('Không thể xóa bình luận'); }
  };

  return { comments, isLoading, addComment, deleteComment };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { Capacitor } from '@capacitor/core';
import { Health, type HealthDataType } from '@capgo/capacitor-health';
import { toast } from 'sonner';

export function useDeviceHealth(profileId?: string) {
  const [isWatchConnected, setIsWatchConnected] = useState(() => {
    if (profileId && profileId !== 'undefined') {
      const prefs = JSON.parse(localStorage.getItem(`digiwell_prefs_${profileId}`) || '{}');
      return !!prefs.watch;
    }
    return false;
  });
  const [watchData, setWatchData] = useState<{ steps: number; heartRate: number }>({ steps: 0, heartRate: 0 });
  const [isLoading, setIsLoading] = useState(false);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  // Check if health data is available on this device
  const checkHealthAvailability = useCallback(async () => {
    if (!Capacitor.isNativePlatform()) return false;

    try {
      const result = await Health.isAvailable();
      return result.available;
    } catch {
      return false;
    }
  }, []);

  // Request permissions and check authorization status
  const requestPermissions = useCallback(async (): Promise<boolean> => {
    if (!Capacitor.isNativePlatform()) {
      toast.info("Tính năng đồng bộ sức khỏe chỉ hoạt động trên thiết bị thật (iOS/Android).");
      return false;
    }

    setIsLoading(true);
    try {
      const available = await checkHealthAvailability();
      if (!available) {
        toast.error("Thiết bị của bạn không hỗ trợ đồng bộ dữ liệu sức khỏe.");
        return false;
      }

      // Request authorization for health data
      await Health.requestAuthorization({
        read: ['steps' as HealthDataType, 'heartRate' as HealthDataType]
      });

      toast.success("Đã cấp quyền truy cập dữ liệu sức khỏe!");
      return true;
    } catch (error: any) {
      console.error('Lỗi khi yêu cầu quyền:', error);
      if (error.message?.includes('denied')) {
        toast.error("Quyền truy cập dữ liệu sức khỏe bị từ chối. Vui lòng cấp quyền trong cài đặt thiết bị.");
      } else {
        toast.error("Không thể kết nối với Apple Health / Health Connect.");
      }
      return false;
    } finally {
      setIsLoading(false);
    }
  }, [checkHealthAvailability]);

  // Sync health data from today
  const syncHealthData = useCallback(async () => {
    if (!isWatchConnected || !Capacitor.isNativePlatform()) return;

    try {
      // Get data from start of today
      const startDate = new Date();
      startDate.setHours(0, 0, 0, 0);
      const endDate = new Date();

      // Fetch steps data
      const stepsRes = await Health.readSamples({
        dataType: 'steps' as HealthDataType,
        startDate: startDate.toISOString(),
        endDate: endDate.toISOString(),
      });

      // Fetch heart rate data (latest reading)
      const hrRes = await Health.readSamples({
        dataType: 'heartRate' as HealthDataType,
        startDate: startDate.toISOString(),
        endDate: endDate.toISOString(),
        limit: 1,
      });

      const totalSteps = stepsRes.samples.reduce((sum: number, entry: any) => sum + entry.value, 0);
      const latestHr = hrRes.samples.length > 0 ? hrRes.samples[0].value : 0;

      setWatchData({ steps: Math.round(totalSteps), heartRate: Math.round(latestHr) });
    } catch (error: any) {
      console.error('Lỗi đồng bộ dữ liệu sức khỏe:', error);
      // Don't disconnect on sync errors, just log them
    }
  }, [isWatchConnected]);

  // Connect to health services
  const connectHealth = useCallback(async () => {
    const hasPermission = await requestPermissions();
    if (hasPermission) {
      setIsWatchConnected(true);
      toast.success("Đã kết nối với Apple Health / Health Connect!");
    }
  }, [requestPermissions]);

  // Disconnect from health services
  const disconnectHealth = useCallback(() => {
    setIsWatchConnected(false);
    setWatchData({ steps: 0, heartRate: 0 });
    toast.info("Đã ngắt kết nối với Apple Health / Health Connect.");
  }, []);

  // Toggle connection
  const toggleHealthConnection = useCallback(async () => {
    if (isWatchConnected) {
      disconnectHealth();
    } else {
      await connectHealth();
    }
  }, [isWatchConnected, connectHealth, disconnectHealth]);

  // Sync data when connected
  useEffect(() => {
    if (isWatchConnected) {
      // Initial sync
      syncHealthData();

      // Set up periodic sync every 5 minutes
      intervalRef.current = setInterval(syncHealthData, 5 * 60 * 1000);

      return () => {
        if (intervalRef.current) {
          clearInterval(intervalRef.current);
        }
      };
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    }
  }, [isWatchConnected, syncHealthData]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  return {
    isWatchConnected,
    watchData,
    isLoading,
    connectHealth,
    disconnectHealth,
    toggleHealthConnection,
    syncHealthData
  };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import type { RealtimePostgresChangesPayload } from '@supabase/supabase-js';

const PAGE_SIZE = 10;

export function useFeed(currentUserId: string | undefined) {
  const [posts, setPosts] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isFetchingMore, setIsFetchingMore] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [newPostsCount, setNewPostsCount] = useState(0);
  const [pendingPosts, setPendingPosts] = useState<any[]>([]);

  const fetchPosts = useCallback(async (offset: number) => {
    if (!currentUserId || currentUserId === 'undefined') return;
    const isFirstPage = offset === 0;
    
    // 1. Load từ Local Cache trước (Offline-First) cho trang đầu
    if (isFirstPage) {
      try {
        const cached = localStorage.getItem(`digiwell_feed_cache`);
        if (cached) {
          setPosts(JSON.parse(cached));
        } else {
          setIsLoading(true);
        }
      } catch(e) {}
    } else {
      setIsFetchingMore(true);
    }

    try {
      const { data, error } = await supabase
        .from('social_posts')
        .select(`
          *,
          author:profiles!social_posts_author_id_fkey (*),
          social_post_likes (user_id)
        `)
        .order('created_at', { ascending: false })
        .range(offset, offset + PAGE_SIZE - 1);

      if (error) throw error;

      if (data) {
        const formatted = data.map((post: any) => ({
          ...post,
          likedByMe: post.social_post_likes?.some((l: any) => l.user_id === currentUserId) ?? false,
        }));

        if (isFirstPage) {
          setPosts(formatted);
          // 2. Cập nhật lại Cache
          localStorage.setItem(`digiwell_feed_cache`, JSON.stringify(formatted));
        }
        else {
          setPosts(prev => {
            const existingIds = new Set(prev.map(p => p.id));
            const newPosts = formatted.filter((p: any) => !existingIds.has(p.id));
            return [...prev, ...newPosts];
          });
        }

        setHasMore(data.length === PAGE_SIZE);
      }
    } catch (err) {
      console.error('Lỗi tải feed:', err);
    } finally {
      setIsLoading(false);
      setIsFetchingMore(false);
    }
  }, [currentUserId]);

  useEffect(() => { fetchPosts(0); }, [fetchPosts]);

  // Supabase Realtime Subscription cho bài mới
  useEffect(() => {
    if (!currentUserId || currentUserId === 'undefined') return;

    // FIX CRASH: Tạo tên channel độc nhất để tránh lỗi tái sử dụng channel cũ trong React Strict Mode
    const channelId = `feed-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    const channel = supabase.channel(channelId);

    channel
      .on(
        'postgres_changes', 
        { event: 'INSERT', schema: 'public', table: 'social_posts' }, 
        async (payload: RealtimePostgresChangesPayload<Record<string, any>>) => {
          const newPost = payload.new as { id: string; [key: string]: any };
          const { data } = await supabase.from('social_posts').select('*, author:profiles!social_posts_author_id_fkey (*)').eq('id', newPost.id).single();
          if (data) {
            setPendingPosts(prev => [data, ...prev]);
            setNewPostsCount(prev => prev + 1);
          }
        }
      )
      .subscribe(); // <-- MUST BE HERE AT THE END

    return () => { 
      supabase.removeChannel(channel); 
    };
  }, [currentUserId]);

  const loadMore = useCallback(() => {
    if (!isLoading && !isFetchingMore && hasMore) fetchPosts(posts.length);
  }, [isLoading, isFetchingMore, hasMore, posts.length, fetchPosts]);

  const showNewPosts = useCallback(() => {
    const formattedPending = pendingPosts.map(p => ({ ...p, likedByMe: false }));
    setPosts(prev => [...formattedPending, ...prev]);
    setPendingPosts([]); setNewPostsCount(0);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [pendingPosts, currentUserId]);

  return { posts, isLoading, isFetchingMore, hasMore, loadMore, newPostsCount, showNewPosts };
}

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';

export function useFollow(targetUserId: string, currentUserId: string | undefined) {
  const [isFollowing, setIsFollowing] = useState(false);

  useEffect(() => {
    if (!currentUserId || !targetUserId) return;
    supabase.from('social_follows').select('id').eq('follower_id', currentUserId).eq('following_id', targetUserId).single()
      .then(({ data }: { data: any }) => setIsFollowing(!!data));
  }, [targetUserId, currentUserId]);

  const toggleFollow = useCallback(async () => {
    if (!currentUserId || !targetUserId) return;
    const prev = isFollowing;
    setIsFollowing(!prev);

    try {
      if (!prev) {
        const { error } = await supabase.from('social_follows').insert({ follower_id: currentUserId, following_id: targetUserId });
        if (error) throw error;
      } else {
        const { error } = await supabase.from('social_follows').delete().eq('follower_id', currentUserId).eq('following_id', targetUserId);
        if (error) throw error;
      }
    } catch (err) { setIsFollowing(prev); toast.error('Lỗi thao tác, thử lại sau'); }
  }, [targetUserId, currentUserId, isFollowing]);

  return { isFollowing, toggleFollow };
}

import { useState, useCallback } from 'react';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import type { Challenge, UserBadge, UserChallenge } from '@/types/gamification';

export function useGamification(userId: string | undefined) {
  const [availableChallenges, setAvailableChallenges] = useState<Challenge[]>([]);
  const [userChallenges, setUserChallenges] = useState<UserChallenge[]>([]);
  const [userBadges, setUserBadges] = useState<UserBadge[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // 1. Fetch Danh sách Thử thách từ Master Table
  const fetchAvailableChallenges = useCallback(async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('challenges')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) setAvailableChallenges(data as Challenge[]);
    } catch (err: any) {
      toast.error(err.message || 'Lỗi tải danh sách thử thách');
    } finally {
      setIsLoading(false);
    }
  }, []);

  // 2. Fetch Thử thách USER ĐANG CHẠY (Tao đã bổ sung hàm này cho đệ)
  const fetchUserChallenges = useCallback(async () => {
    if (!userId || userId === 'undefined') return;
    try {
      const { data, error } = await supabase
        .from('user_challenges')
        .select('*, challenge:challenges(*)')
        .eq('user_id', userId)
        .eq('status', 'active')
        .order('joined_at', { ascending: false });

      if (error) throw error;
      if (data) setUserChallenges(data as UserChallenge[]);
    } catch (err: any) {
      console.error('Lỗi tải thử thách của user:', err.message);
    }
  }, [userId]);

  // 3. Fetch Huy hiệu đã mở khoá của User
  const fetchUserBadges = useCallback(async () => {
    if (!userId || userId === 'undefined') return;
    try {
      const { data, error } = await supabase
        .from('user_badges')
        .select('*, badge:badges(*)')
        .eq('user_id', userId)
        .order('unlocked_at', { ascending: false });

      if (error) throw error;
      if (data) setUserBadges(data as UserBadge[]);
    } catch (err: any) {
      console.error('Lỗi tải huy hiệu:', err.message);
    }
  }, [userId]);

  // 4. Tham gia Thử thách (Giao dịch an toàn qua RPC)
  const joinChallenge = async (challengeId: string, stakeWp: number) => {
    if (!userId || userId === 'undefined') {
      toast.error('Bạn cần đăng nhập để tham gia!');
      return false;
    }
    const toastId = toast.loading('Đang làm thủ tục đóng họ...');

    try {
      // Gọi hàm RPC Backend
      const { error } = await supabase.rpc('join_challenge', {
        p_user_id: userId,
        p_challenge_id: challengeId,
        p_stake_wp: stakeWp
      });

      if (error) {
        throw new Error(error.message);
      }

      toast.success(`Chốt kèo thành công! Đã cược ${stakeWp} WP.`, { id: toastId, icon: '🔥' });
      
      // Optimistic Update: Thêm thử thách vào state hiện tại để UI cập nhật tức thì
      const joinedChallenge = availableChallenges.find(c => c.id === challengeId);
      if (joinedChallenge) {
        setUserChallenges(prev => [{
          id: `temp-${Date.now()}`,
          user_id: userId,
          challenge_id: challengeId,
          status: 'active',
          progress_days: 0,
          joined_at: new Date().toISOString(),
          challenge: joinedChallenge
        }, ...prev]);
      }
      return true;
    } catch (err: any) {
      toast.error(err.message || 'Lỗi khi tham gia thử thách', { id: toastId });
      return false;
    }
  };

  // Đã export đầy đủ các hàm ra ngoài
  return {
    availableChallenges, 
    userChallenges, 
    userBadges, 
    isLoading,
    fetchAvailableChallenges, 
    fetchUserChallenges, 
    fetchUserBadges, 
    joinChallenge
  };
}

import { useState, useCallback, useEffect, useRef } from 'react';
import { toast } from 'sonner';
import { 
  generateHydrationAdvice, 
  sendAiChatMessage, 
  type AiChatMessage, 
  type DigiwellAiContext 
} from '../lib/ai';

export interface UseGeminiAIProps {
  profile: any;
  waterIntake: number;
  waterGoal: number;
  weatherData: any;
  watchData: any;
  isWeatherSynced: boolean;
  isWatchConnected: boolean;
  handleAddWater: (amount: number, factor: number, name: string) => Promise<void>;
  setShowAiChat?: (show: boolean) => void;
  handleExportPDF?: () => Promise<void>;
  toggleFastingMode?: () => void;
  setShowHistory?: (show: boolean) => void;
}

const defaultWelcomeMessage: AiChatMessage = {
  role: 'model',
  content: 'Chào đệ! Hôm nay DigiCoach đã sẵn sàng đồng hành cùng đệ. Hãy bắt đầu bằng cách uống một ly nước nhé!'
};

export function useGeminiAI(props: UseGeminiAIProps) {
  const {
    profile, waterIntake, waterGoal, weatherData, watchData,
    isWeatherSynced, isWatchConnected, handleAddWater, setShowAiChat,
    handleExportPDF, toggleFastingMode, setShowHistory
  } = props;

  // [BÍ QUYẾT TỐI ƯU] Dùng Ref để lưu trữ props mới nhất mà KHÔNG kích hoạt re-render
  // Giải quyết dứt điểm lỗi vòng lặp vô hạn do App.tsx re-render mỗi giây
  const propsRef = useRef(props);
  useEffect(() => { propsRef.current = props; });

  // --- [1] STATES ---
  const [aiAdvice, setAiAdvice] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [chatMessages, setChatMessages] = useState<AiChatMessage[]>([defaultWelcomeMessage]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [chatInput, setChatInput] = useState('');
  const isFetchingAdviceRef = useRef(false);
  const isChattingRef = useRef(false);
  const hasFetchedInitialAdvice = useRef(false);

  // Clean chat khi logout
  useEffect(() => {
    if (!profile?.id) {
      setChatMessages([defaultWelcomeMessage]);
      setAiAdvice('');
      hasFetchedInitialAdvice.current = false; // Reset cờ để user mới đăng nhập vẫn nhận được lời khuyên
    }
  }, [profile?.id]);

  // --- [2] BUILD CONTEXT (Gom dữ liệu gửi cho AI) ---
  const buildContext = useCallback((): DigiwellAiContext => {
    const p = propsRef.current;
    return {
      nowIso: new Date().toISOString(),
      waterIntake: p.waterIntake,
      waterGoal: p.waterGoal,
      weather: (p.isWeatherSynced && p.weatherData) ? { 
        temp: p.weatherData.temp, 
        status: p.weatherData.status || '', 
        location: p.weatherData.location || '' 
      } : undefined,
      watch: (p.isWatchConnected && p.watchData) ? {
        heartRate: p.watchData.heartRate,
        steps: p.watchData.steps
      } : undefined,
      profile: p.profile ? {
        nickname: p.profile.nickname,
        goal: p.profile.goal,
        activity: p.profile.activity,
        climate: p.profile.climate
      } : undefined
    };
  }, []); // Ngắt hoàn toàn vòng lặp do loại bỏ dependencies cập nhật thường xuyên

  // --- [3] ACTIONS ---

  // Lấy lời khuyên nhanh (Tab Insight)
  const fetchAIAdvice = useCallback(async () => {
    if (!propsRef.current.profile?.id) return;
    
    if (isFetchingAdviceRef.current || isAiLoading) {
      console.warn("🛡️ [GUARD] API Call prevented to save quota");
      return;
    }

    isFetchingAdviceRef.current = true;
    setIsAiLoading(true);
    console.warn("🚀 [API CALL] Sending to Gemini...");
    
    try {
      const advice = await generateHydrationAdvice(buildContext());
      setAiAdvice(advice);
    } catch (error) {
      console.error("Lỗi AI Advice:", error);
    } finally {
      setIsAiLoading(false);
      setTimeout(() => { isFetchingAdviceRef.current = false; }, 2000); // Debounce 2s để tránh dính lỗi 429
    }
  }, [buildContext, isAiLoading]);

  // Tự động gọi lời khuyên 1 lần duy nhất khi load Profile (Mount)
  useEffect(() => {
    if (propsRef.current.profile?.id && !hasFetchedInitialAdvice.current) {
      hasFetchedInitialAdvice.current = true;
      fetchAIAdvice();
    }
  }, []); // Empty dependency array forces this to run strictly ONCE

  // Chat và điều khiển hệ thống
  const handleSendChatMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    
    if (!chatInput.trim()) return;
    
    if (isChatLoading || isChattingRef.current) {
      console.warn("🛡️ [GUARD] API Call prevented to save quota");
      return;
    }

    isChattingRef.current = true;
    const userText = chatInput.trim();
    const userMsg: AiChatMessage = { role: 'user', content: userText };
    
    // Đẩy tin nhắn của mình lên trước cho thật (UI/UX)
    setChatMessages((prev: AiChatMessage[]) => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    
    console.warn("🚀 [API CALL] Sending to Gemini...");

    try {
      const { reply, waterAction } = await sendAiChatMessage(userText, buildContext());
      
      const assistantMsg: AiChatMessage = { role: 'model', content: reply };
      setChatMessages((prev: AiChatMessage[]) => [...prev, assistantMsg]);

      // --- [PHẪU THUẬT LOGIC: AI ĐIỀU KHIỂN APP] ---
      const p = propsRef.current;
      
      // 1. Nếu AI nhận diện hành động uống nước
      if (waterAction && p.handleAddWater) {
        await p.handleAddWater(waterAction.amount, waterAction.factor, waterAction.name);
        toast.success(`AI đã ghi nhận: ${waterAction.amount}ml ${waterAction.name}`);
      }
      
      // 2. Phân tích ý định (Intent Parsing) để đóng modal và mở tính năng tương ứng
      const lowerReply = reply.toLowerCase();
      
      // Tránh việc AI chỉ đang "nói về" báo cáo mà mình đã xuất. 
      // Chỉ kích hoạt nếu có các từ khóa mang tính hành động.
      const shouldTriggerAction = (keywords: string[]) => keywords.some(kw => lowerReply.includes(kw));

      if (shouldTriggerAction(['báo cáo', 'xuất pdf', 'tạo file']) && p.handleExportPDF) {
        toast.info("Đang tạo báo cáo sức khỏe...");
        p.setShowAiChat?.(false);
        setTimeout(p.handleExportPDF, 500); // Delay nhẹ để UI đóng mượt
      } 
      else if (shouldTriggerAction(['lịch sử', 'uống khi nào', 'xem lại']) && p.setShowHistory) {
        p.setShowAiChat?.(false);
        p.setShowHistory?.(true);
      } 
      else if (shouldTriggerAction(['nhịn ăn', 'fasting', 'giờ ăn']) && p.toggleFastingMode) {
        p.setShowAiChat?.(false);
        p.toggleFastingMode?.();
      }

    } catch (error: any) {
      toast.error('AI đang bận hớp nước, đệ thử lại sau nhé!');
    } finally {
      setIsChatLoading(false);
      setTimeout(() => { isChattingRef.current = false; }, 1000); // 1s debounce
    }
  };

  return {
    aiAdvice, 
    isAiLoading, 
    chatMessages, 
    setChatMessages,
    isChatLoading, 
    chatInput, 
    setChatInput, 
    fetchAIAdvice, 
    handleSendChatMessage
  };
}

import { useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';

export function useLike(postId: string, currentUserId: string | undefined, initialLiked: boolean, initialCount: number) {
  const [isLiked, setIsLiked] = useState(initialLiked);
  const [count, setCount] = useState(initialCount);

  const toggleLike = useCallback(async () => {
    if (!currentUserId) return;
    const prevLiked = isLiked;
    const prevCount = count;

    // Optimistic Update
    setIsLiked(!prevLiked);
    setCount(prevCount + (prevLiked ? -1 : 1));

    try {
      if (!prevLiked) {
        const { error } = await supabase.from('social_post_likes').insert({ post_id: postId, user_id: currentUserId });
        if (error) throw error;
      } else {
        const { error } = await supabase.from('social_post_likes').delete().eq('post_id', postId).eq('user_id', currentUserId);
        if (error) throw error;
      }
    } catch (err) {
      setIsLiked(prevLiked); // Revert on fail
      setCount(prevCount);
      toast.error('Không thể thích bài, thử lại sau');
    }
  }, [postId, currentUserId, isLiked, count]);

  return { isLiked, count, toggleLike };
}

