import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import { claimQuestReward, provisionUserQuests, syncLevelQuestProgress } from '@/lib/questEngine';
import type { UserQuest, QuestType } from '../config/questConfig';
import { resolveQuestProgress } from '@/lib/questProgress';

export function useQuests(userId: string | undefined, userLevel: number = 1) {
  const [quests,  setQuests]  = useState<UserQuest[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchQuests = useCallback(async () => {
    if (!userId) return;

    // 1. Load từ Local Cache trước (Offline-First)
    try {
      const cached = localStorage.getItem(`digiwell_quests_cache_${userId}`);
      if (cached) {
        setQuests(normalizeFetchedQuests(JSON.parse(cached), userLevel));
        setLoading(false); // Có data rồi thì không block UI
      } else {
        setLoading(true);
      }
    } catch(e) {}

    try {
      // 2. Fetch fresh data ngầm
      await provisionUserQuests(userId, userLevel);
      await syncLevelQuestProgress(userId, userLevel);

      const today     = new Date().toLocaleDateString('en-CA');
      const weekStart = getWeekStart();

      const { data, error } = await supabase
        .from('user_quests')
        .select(`
          id, quest_id, status, progress, reset_date, completed_at, claimed_at,
          quest:quests (
            id, type, title, description, condition_type, condition_value,
            reward_exp, reward_coins, reward_badge_id, min_level
          )
        `)
        .eq('user_id', userId)
        .or(
          `reset_date.is.null,reset_date.eq.${today},reset_date.eq.${weekStart}`,
        )
        .order('status', { ascending: true }); // active trước, completed sau

      if (error) throw error;

      const formattedData = normalizeFetchedQuests((data ?? []) as unknown as UserQuest[], userLevel);
      setQuests(formattedData);

      // 3. Cập nhật lại Cache
      localStorage.setItem(`digiwell_quests_cache_${userId}`, JSON.stringify(formattedData));
    } catch (err) {
      console.error('[useQuests] fetch:', err);
    } finally {
      setLoading(false);
    }
  }, [userId, userLevel]);

  useEffect(() => { fetchQuests(); }, [fetchQuests]);

  const claim = useCallback(async (userQuestId: string) => {
    if (!userId) return;
    const result = await claimQuestReward(userId, userQuestId);
    if (result) {
      // Update local state ngay, không cần refetch
      setQuests(prev =>
        prev.map(uq =>
          uq.id === userQuestId
            ? { ...uq, status: 'claimed', claimed_at: new Date().toISOString() }
            : uq,
        ),
      );
    }
    return result;
  }, [userId]);

  // Filter helpers
  const byType = (type: QuestType) =>
    quests.filter(uq => uq.quest.type === type);

  return {
    quests,
    loading,
    dailyQuests:   byType('daily'),
    weeklyQuests:  byType('weekly'),
    levelQuests:   byType('level'),
    claimQuest:    claim,
    refetch:       fetchQuests,
  };
}

function normalizeFetchedQuests(rows: UserQuest[], userLevel: number): UserQuest[] {
  return rows.map((uq) => {
    const quest = Array.isArray((uq as any).quest) ? (uq as any).quest[0] : uq.quest;
    if (!quest) return uq;

    const resolved = resolveQuestProgress(quest, { level: userLevel });
    const isLevelQuest = resolved.normalizedType === 'level';

    return {
      ...uq,
      progress: isLevelQuest ? Math.max(Number(uq.progress || 0), resolved.progress) : Number(uq.progress || 0),
      status: uq.status === 'claimed'
        ? 'claimed'
        : isLevelQuest && resolved.completed
          ? 'completed'
          : uq.status,
      quest: {
        ...quest,
        condition_type: resolved.normalizedType as any,
        condition_value: resolved.target,
      },
    };
  });
}

// ── Week start helper ──────────────────────────────────────

function getWeekStart(): string {
  const d   = new Date();
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1);
  d.setDate(diff);
  return d.toLocaleDateString('en-CA');
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';

export interface AppSettings {
  displayName: string;
  avatarUrl: string;
  weight: number;
  height: number;
  age: number;
  gender: string;
  activity: string;
  climate: string;
  waterGoal: number;
  autoWaterGoal: boolean;
  syncHealth: boolean;
  smartReminders: boolean;
  reminderFrequency: '30 phút' | '1 giờ' | '2 giờ';
  quietHoursStart: string;
  quietHoursEnd: string;
  hapticsEnabled: boolean;
  unit: 'ml' | 'oz';
  themeColor: string;
  biometricEnabled: boolean;
}

const DEFAULT_SETTINGS: AppSettings = {
  displayName: '',
  avatarUrl: '',
  weight: 60,
  height: 170,
  age: 20,
  gender: 'Nam',
  activity: 'Bình thường',
  climate: 'Ôn hòa',
  waterGoal: 2000,
  autoWaterGoal: true,
  syncHealth: false,
  smartReminders: true,
  reminderFrequency: '1 giờ',
  quietHoursStart: '22:00',
  quietHoursEnd: '07:00',
  hapticsEnabled: true,
  unit: 'ml',
  themeColor: '#06b6d4', // Cyan
  biometricEnabled: false,
};

export function useSettings(profile: any) {
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSync, setLastSync] = useState<Date | null>(null);

  // Load initial data
  useEffect(() => {
    if (!profile?.id) return;
    
    const localKey = `digiwell_settings_${profile.id}`;
    const cached = localStorage.getItem(localKey);
    
    if (cached) {
      setSettings({ 
        ...DEFAULT_SETTINGS, 
        ...JSON.parse(cached), 
        displayName: profile.nickname || profile.name || '', 
        avatarUrl: profile.avatar_url || JSON.parse(cached).avatarUrl || '',
        weight: profile.weight || 60, 
        height: profile.height || 170, 
        age: profile.age || 20,
        gender: profile.gender || 'Nam',
        activity: profile.activity || 'Bình thường',
        climate: profile.climate || 'Ôn hòa',
        waterGoal: profile.water_goal || JSON.parse(cached).waterGoal || 2000, // Ưu tiên data từ Supabase
        biometricEnabled: localStorage.getItem('biometric_enabled') === 'true'
      });
    } else {
      setSettings(prev => ({
        ...prev,
        displayName: profile.nickname || profile.name || '',
        avatarUrl: profile.avatar_url || '',
        weight: profile.weight || 60,
        height: profile.height || 170,
        age: profile.age || 20,
        gender: profile.gender || 'Nam',
        activity: profile.activity || 'Bình thường',
        climate: profile.climate || 'Ôn hòa',
        biometricEnabled: localStorage.getItem('biometric_enabled') === 'true',
        waterGoal: profile.water_goal || 2000
      }));
    }
  }, [profile]);

  // Provide haptic feedback utility (Chỉ dùng cho UI gọi)
  const triggerHaptic = useCallback(() => {
    if (settings.hapticsEnabled && navigator.vibrate) {
      navigator.vibrate(50);
    }
  }, [settings.hapticsEnabled]);

  // Save to LocalStorage & Supabase
  const updateSettings = useCallback(async (newValues: Partial<AppSettings>) => {
    if (!profile?.id || profile.id === 'undefined') return;
    
    setIsSaving(true);
    
    const updatedSettings = { ...settings, ...newValues };
    setSettings(updatedSettings);
    
    // 1. Save to LocalStorage (Instant UI feedback)
    localStorage.setItem(`digiwell_settings_${profile.id}`, JSON.stringify(updatedSettings));

    // Apply Theme Color instantly
    if (newValues.themeColor) {
      document.documentElement.style.setProperty('--color-primary', newValues.themeColor);
    }

    // 2. Sync to Supabase in background
    try {
      // Đẩy đầy đủ các field quan trọng lên database
      const { error } = await supabase.from('profiles').update({
        avatar_url: updatedSettings.avatarUrl,
        nickname: updatedSettings.displayName,
        weight: updatedSettings.weight,
        height: updatedSettings.height,
        age: updatedSettings.age,
        gender: updatedSettings.gender,
        activity: updatedSettings.activity,
        climate: updatedSettings.climate,
        water_goal: updatedSettings.waterGoal, // Đã thêm water_goal để không bị mất data
        updated_at: new Date().toISOString()
      }).eq('id', profile.id);

      if (error) throw error;
      setLastSync(new Date());
    } catch (error) {
      console.error('Lỗi đồng bộ Settings:', error);
      toast.message('Đã lưu cục bộ — sẽ đồng bộ khi có mạng', {
        description: 'Dữ liệu của bạn được an toàn.',
      });
    } finally {
      setIsSaving(false);
    }
  }, [settings, profile?.id]);

  return { settings, updateSettings, isSaving, lastSync, triggerHaptic };
}

import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'sonner';
import { supabase } from '../lib/supabase';
import {
  buildProgressShareText,
  DEFAULT_SOCIAL_COMPOSER,
  DEFAULT_SOCIAL_PROFILE_STATS,
  isMissingSocialSchemaError,
  type SocialComposerState,
  type SocialDiscoverProfile,
  type SocialFeedPost,
  type SocialProfileStats,
} from '../lib/social';

interface UseSocialDataProps {
  profile: any;
  waterIntake: number;
  waterGoal: number;
  streak: number;
  activeTab: string;
  setActiveTab: (tab: any) => void;
}

export function useSocialData({ profile, waterIntake, waterGoal, streak, activeTab, setActiveTab }: UseSocialDataProps) {
  const [showSocialComposer, setShowSocialComposer] = useState(false);
  const [showDiscoverPeople, setShowDiscoverPeople] = useState(false);
  const [showSocialProfile, setShowSocialProfile] = useState(false);
  const [socialComposer, setSocialComposer] = useState<SocialComposerState>({ ...DEFAULT_SOCIAL_COMPOSER });
  const [socialPosts, setSocialPosts] = useState<SocialFeedPost[]>([]);
  const [socialStories, setSocialStories] = useState<SocialFeedPost[]>([]);
  const [socialSearchQuery, setSocialSearchQuery] = useState('');
  const [socialSearchResults, setSocialSearchResults] = useState<SocialDiscoverProfile[]>([]);
  const [socialFollowingIds, setSocialFollowingIds] = useState<string[]>([]);
  const [socialProfileStats, setSocialProfileStats] = useState<SocialProfileStats>(DEFAULT_SOCIAL_PROFILE_STATS);
  const [socialError, setSocialError] = useState('');
  const [isSocialLoading, setIsSocialLoading] = useState(false);
  const [isPublishingSocialPost, setIsPublishingSocialPost] = useState(false);
  const [isSocialSearching, setIsSocialSearching] = useState(false);
  const [socialImageFile, setSocialImageFile] = useState<File | null>(null);
  const [socialImagePreview, setSocialImagePreview] = useState('');
  const socialImageInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!profile?.id) {
      setShowSocialComposer(false);
      setShowDiscoverPeople(false);
      setShowSocialProfile(false);
      setSocialPosts([]);
      setSocialStories([]);
      setSocialSearchResults([]);
      setSocialFollowingIds([]);
      setSocialProfileStats(DEFAULT_SOCIAL_PROFILE_STATS);
      setSocialError('');
      resetSocialComposer();
    }
  }, [profile?.id]);

  useEffect(() => {
    if (activeTab === 'feed' && profile?.id) {
      void refreshSocialFeed();
    }
  }, [activeTab, profile?.id]);

  useEffect(() => {
    if (showDiscoverPeople && profile?.id) {
      void loadSocialDirectory(socialSearchQuery);
    }
  }, [showDiscoverPeople, profile?.id]);

  useEffect(() => () => {
    if (socialImagePreview.startsWith('blob:')) {
      URL.revokeObjectURL(socialImagePreview);
    }
  }, [socialImagePreview]);

  const getSocialErrorMessage = (message?: string) => {
    if (!message) return 'Không thể tải tính năng cộng đồng lúc này.';
    if (isMissingSocialSchemaError(message)) {
      return 'Social chưa được bật trên Supabase. Hãy chạy file supabase/social_lite.sql rồi mở lại app.';
    }
    return message;
  };

  const resetSocialComposer = () => {
    if (socialImagePreview.startsWith('blob:')) {
      URL.revokeObjectURL(socialImagePreview);
    }
    setSocialComposer({ ...DEFAULT_SOCIAL_COMPOSER });
    setSocialImageFile(null);
    setSocialImagePreview('');
  };

  const closeSocialComposer = () => {
    resetSocialComposer();
    setShowSocialComposer(false);
  };

  const openSocialComposer = (kind: SocialComposerState['postKind'] = 'status') => {
    if (!profile?.id) {
      toast.error('Vui lòng đăng nhập lại để đăng bài.');
      return;
    }

    const content = kind === 'progress'
      ? buildProgressShareText({
        nickname: profile.nickname,
        waterIntake,
        waterGoal,
        streak,
      })
      : '';

    resetSocialComposer();
    setSocialComposer({
      content,
      imageUrl: '',
      postKind: kind,
      visibility: kind === 'story' ? 'followers' : 'public',
    });
    setActiveTab('feed');
    setShowSocialComposer(true);
  };

  const uploadSocialImage = async (file: File) => {
    if (!profile?.id) throw new Error('Vui lòng đăng nhập lại.');

    const extension = file.name.includes('.') ? file.name.split('.').pop()?.toLowerCase() : 'jpg';
    const safeExtension = extension || 'jpg';
    const filePath = `${profile.id}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${safeExtension}`;
    const { error } = await supabase!.storage.from('social-media').upload(filePath, file, {
      cacheControl: '3600',
      upsert: false,
      contentType: file.type || undefined,
    });
    if (error) throw error;
    return supabase!.storage.from('social-media').getPublicUrl(filePath).data.publicUrl;
  };

  const loadSocialDirectory = async (query: string) => {
    if (!profile?.id) return;

    setIsSocialSearching(true);
    try {
      const keyword = query.trim();
      let request = supabase!
        .from('profiles')
        .select('id, nickname')
        .neq('id', profile.id);

      request = keyword.length >= 2
        ? request.ilike('nickname', `%${keyword}%`)
        : request.order('nickname', { ascending: true });

      const { data, error } = await request.limit(8);
      if (error) throw error;

      setSocialError('');
      setSocialSearchResults((data || []).map((user: any, index: number) => ({
        id: user.id || `search-user-fallback-${index}`,
        nickname: user.nickname || 'Người dùng DigiWell',
        isFollowing: socialFollowingIds.includes(user.id),
      })));
    } catch (err: any) {
      const friendlyMessage = getSocialErrorMessage(err.message);
      setSocialError(friendlyMessage);
      toast.error(friendlyMessage);
    } finally {
      setIsSocialSearching(false);
    }
  };

  const refreshSocialFeed = async (options?: { silent?: boolean }) => {
    if (!profile?.id) return;

    if (!options?.silent) {
      setIsSocialLoading(true);
    }

    try {
      const [
        followingRes,
        followersCountRes,
        followingCountRes,
        postsCountRes,
      ] = await Promise.all([
        supabase!.from('social_follows').select('following_id').eq('follower_id', profile.id),
        supabase!.from('social_follows').select('*', { count: 'exact', head: true }).eq('following_id', profile.id),
        supabase!.from('social_follows').select('*', { count: 'exact', head: true }).eq('follower_id', profile.id),
        supabase!.from('social_posts').select('*', { count: 'exact', head: true }).eq('author_id', profile.id),
      ]);

      if (followingRes.error) throw followingRes.error;
      if (followersCountRes.error) throw followersCountRes.error;
      if (followingCountRes.error) throw followingCountRes.error;
      if (postsCountRes.error) throw postsCountRes.error;

      const followingIds = (followingRes.data || []).map((row: any) => row.following_id);
      setSocialFollowingIds(followingIds);
      setSocialProfileStats({
        followers: followersCountRes.count || 0,
        following: followingCountRes.count || 0,
        posts: postsCountRes.count || 0,
      });

      const feedAuthorIds = Array.from(new Set([profile.id, ...followingIds]));
      const { data: postRows, error: postsError } = await supabase!
        .from('social_posts')
        .select('id, author_id, content, image_url, post_kind, visibility, hydration_ml, streak_snapshot, like_count, created_at, expires_at')
        .in('author_id', feedAuthorIds)
        .order('created_at', { ascending: false })
        .limit(40);

      if (postsError) throw postsError;

      const validRows = (postRows || []).filter((row: any) => {
        if (row.post_kind !== 'story') return true;
        if (!row.expires_at) return false;
        return new Date(row.expires_at).getTime() > Date.now();
      });

      const authorIds = Array.from(new Set(validRows.map((row: any) => row.author_id)));
      const postIds = validRows.map((row: any) => row.id);

      const [profilesRes, likesRes] = await Promise.all([
        authorIds.length > 0
          ? supabase!.from('profiles').select('id, nickname').in('id', authorIds)
          : Promise.resolve({ data: [], error: null }),
        postIds.length > 0
          ? supabase!.from('social_post_likes').select('post_id').eq('user_id', profile.id).in('post_id', postIds)
          : Promise.resolve({ data: [], error: null }),
      ]);

      if (profilesRes.error) throw profilesRes.error;
      if (likesRes.error) throw likesRes.error;

      const profileMap = new Map((profilesRes.data || []).map((row: any) => [row.id, {
        id: row.id,
        nickname: row.nickname || 'Người dùng DigiWell',
      }]));
      const likedPostIds = new Set((likesRes.data || []).map((row: any) => row.post_id));

      const mappedPosts: SocialFeedPost[] = validRows.map((row: any, index: number) => ({
        ...row,
        id: row.id || `post-fallback-${index}`,
        author: profileMap.get(row.author_id) || {
          id: row.author_id,
          nickname: row.author_id === profile.id ? (profile.nickname || 'Bạn') : 'Người dùng DigiWell',
        },
        likedByMe: likedPostIds.has(row.id),
      }));

      const storyMap = new Map<string, SocialFeedPost>();
      const latestStories = mappedPosts
        .filter(post => post.post_kind === 'story')
        .reduce<SocialFeedPost[]>((acc: SocialFeedPost[], post: SocialFeedPost) => {
          if (storyMap.has(post.author_id)) return acc;
          storyMap.set(post.author_id, post);
          acc.push(post);
          return acc;
        }, []);

      setSocialStories(latestStories);
      setSocialPosts(mappedPosts.filter(post => post.post_kind !== 'story'));
      setSocialError('');
    } catch (err: any) {
      const friendlyMessage = getSocialErrorMessage(err.message);
      setSocialError(friendlyMessage);
      setSocialPosts([]);
      setSocialStories([]);
      if (!options?.silent) {
        toast.error(friendlyMessage);
      }
    } finally {
      setIsSocialLoading(false);
    }
  };

  const handleSocialImagePicked = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Chỉ hỗ trợ ảnh JPG, PNG, WEBP hoặc HEIC.');
      event.target.value = '';
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error('Ảnh tối đa 5MB để upload nhanh hơn.');
      event.target.value = '';
      return;
    }

    if (socialImagePreview.startsWith('blob:')) {
      URL.revokeObjectURL(socialImagePreview);
    }

    const previewUrl = URL.createObjectURL(file);
    setSocialImageFile(file);
    setSocialImagePreview(previewUrl);
    setSocialComposer((prev: SocialComposerState) => ({ ...prev, imageUrl: '' }));
    event.target.value = '';
  };

  const handleSearchSocialUsers = async (query: string) => {
    setSocialSearchQuery(query);
    await loadSocialDirectory(query);
  };

  const handleFollowUser = async (targetUserId: string, nickname: string) => {
    if (!profile?.id) return;

    const toastId = toast.loading(`Đang theo dõi ${nickname}...`);
    try {
      const { error } = await supabase!
        .from('social_follows')
        .insert({ follower_id: profile.id, following_id: targetUserId });
      if (error) throw error;

      setSocialFollowingIds((prev: string[]) => prev.includes(targetUserId) ? prev : [...prev, targetUserId]);
      setSocialSearchResults((prev: SocialDiscoverProfile[]) => prev.map(user => user.id === targetUserId ? { ...user, isFollowing: true } : user));
      setSocialProfileStats((prev: SocialProfileStats) => ({ ...prev, following: prev.following + 1 }));
      toast.success(`Đã theo dõi ${nickname}.`, { id: toastId });
      await refreshSocialFeed({ silent: true });
    } catch (err: any) {
      toast.error(getSocialErrorMessage(err.message), { id: toastId });
    }
  };

  const handleUnfollowUser = async (targetUserId: string, nickname: string) => {
    if (!profile?.id) return;

    const toastId = toast.loading(`Đang bỏ theo dõi ${nickname}...`);
    try {
      const { error } = await supabase!
        .from('social_follows')
        .delete()
        .eq('follower_id', profile.id)
        .eq('following_id', targetUserId);
      if (error) throw error;

      setSocialFollowingIds((prev: string[]) => prev.filter(id => id !== targetUserId));
      setSocialSearchResults((prev: SocialDiscoverProfile[]) => prev.map(user => user.id === targetUserId ? { ...user, isFollowing: false } : user));
      setSocialProfileStats((prev: SocialProfileStats) => ({ ...prev, following: Math.max(prev.following - 1, 0) }));
      toast.success(`Đã bỏ theo dõi ${nickname}.`, { id: toastId });
      await refreshSocialFeed({ silent: true });
    } catch (err: any) {
      toast.error(getSocialErrorMessage(err.message), { id: toastId });
    }
  };

  const handleToggleLikePost = async (post: SocialFeedPost) => {
    if (!profile?.id) return;

    const nextLiked = !post.likedByMe;
    const likeDelta = nextLiked ? 1 : -1;
    setSocialPosts((prev: SocialFeedPost[]) => prev.map(item => item.id === post.id ? {
      ...item,
      likedByMe: nextLiked,
      like_count: Math.max((item.like_count || 0) + likeDelta, 0),
    } : item));
    setSocialStories((prev: SocialFeedPost[]) => prev.map(item => item.id === post.id ? {
      ...item,
      likedByMe: nextLiked,
      like_count: Math.max((item.like_count || 0) + likeDelta, 0),
    } : item));

    try {
      // Validate user ID
      if (!profile?.id || profile.id === 'undefined') {
        console.error('[useSocialData] Invalid user ID for like:', profile?.id);
        toast.error('Vui lòng đăng nhập lại');
        return;
      }

      if (nextLiked) {
        const { error } = await supabase!.from('social_post_likes').insert({
          post_id: post.id,
          user_id: profile.id,
        });
        if (error) throw error;
      } else {
        const { error } = await supabase!.from('social_post_likes')
          .delete()
          .eq('post_id', post.id)
          .eq('user_id', profile.id);
        if (error) throw error;
      }

      const { error: countError } = await supabase!.from('social_posts')
        .update({ like_count: Math.max((post.like_count || 0) + likeDelta, 0) })
        .eq('id', post.id);
      if (countError) throw countError;
    } catch (err: any) {
      setSocialPosts((prev: SocialFeedPost[]) => prev.map(item => item.id === post.id ? post : item));
      setSocialStories((prev: SocialFeedPost[]) => prev.map(item => item.id === post.id ? post : item));
      toast.error(getSocialErrorMessage(err.message));
    }
  };

  const handlePublishSocialPost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!profile?.id) return;

    const trimmedContent = socialComposer.content.trim();
    const trimmedImageUrl = socialComposer.imageUrl.trim();

    if (!trimmedContent && !trimmedImageUrl && !socialImageFile) {
      toast.error('Viết gì đó hoặc thêm ảnh trước khi đăng.');
      return;
    }

    setIsPublishingSocialPost(true);
    const toastId = toast.loading(socialComposer.postKind === 'story' ? 'Đang đăng story...' : 'Đang đăng bài...');

    try {
      let imageUrl = trimmedImageUrl || null;
      if (socialImageFile) {
        imageUrl = await uploadSocialImage(socialImageFile);
      }

      const expiresAt = socialComposer.postKind === 'story'
        ? new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
        : null;

      const { error } = await supabase!.from('social_posts').insert({
        author_id: profile.id,
        content: trimmedContent,
        image_url: imageUrl,
        post_kind: socialComposer.postKind,
        visibility: socialComposer.visibility,
        hydration_ml: waterIntake,
        streak_snapshot: streak,
        expires_at: expiresAt,
      });
      if (error) throw error;

      toast.success(
        socialComposer.postKind === 'story' ? 'Story đã lên sóng 24 giờ.' : 'Bài đăng đã xuất hiện trên feed.',
        { id: toastId },
      );
      closeSocialComposer();
      await refreshSocialFeed({ silent: true });
    } catch (err: any) {
      toast.error(getSocialErrorMessage(err.message), { id: toastId });
    } finally {
      setIsPublishingSocialPost(false);
    }
  };

  return {
    showSocialComposer, setShowSocialComposer,
    showDiscoverPeople, setShowDiscoverPeople,
    showSocialProfile, setShowSocialProfile,
    socialComposer, setSocialComposer,
    socialPosts, setSocialPosts,
    socialStories, setSocialStories,
    socialSearchQuery, setSocialSearchQuery,
    socialSearchResults, setSocialSearchResults,
    socialFollowingIds, setSocialFollowingIds,
    socialProfileStats, setSocialProfileStats,
    socialError, setSocialError,
    isSocialLoading, setIsSocialLoading,
    isPublishingSocialPost, setIsPublishingSocialPost,
    isSocialSearching, setIsSocialSearching,
    socialImageFile, setSocialImageFile,
    socialImagePreview, setSocialImagePreview,
    socialImageInputRef,
    closeSocialComposer,
    openSocialComposer,
    handleSocialImagePicked,
    handleSearchSocialUsers,
    handleFollowUser,
    handleUnfollowUser,
    handleToggleLikePost,
    handlePublishSocialPost
  };
}

import { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

export function useStreak(userId: string | undefined, waterGoal: number, todayIntake: number, isPremium: boolean = false) {
  const [pastStreak, setPastStreak] = useState(0);
  const [streakFreezes, setStreakFreezes] = useState(0);
  const [lastFreezeReset, setLastFreezeReset] = useState<string>('');

  // Reset streak freezes monthly for premium users
  useEffect(() => {
    if (!userId || userId === 'undefined' || !isPremium) return;

    const today = new Date().toLocaleDateString('en-CA');
    const currentMonth = today.substring(0, 7); // YYYY-MM

    if (lastFreezeReset !== currentMonth) {
      // Reset streak freezes to 2 per month
      supabase
        .from('profiles')
        .update({ streak_freezes: 2 })
        .eq('id', userId)
        .then(() => {
          setStreakFreezes(2);
          setLastFreezeReset(currentMonth);
        });
    }
  }, [userId, isPremium, lastFreezeReset]);

  useEffect(() => {
    if (!userId || userId === 'undefined' || !waterGoal) return;

    let isActive = true;

    const fetchStreakData = async () => {
      // Fetch streak freezes for premium users
      if (isPremium) {
        const { data: profile } = await supabase
          .from('profiles')
          .select('streak_freezes')
          .eq('id', userId)
          .single();

        if (isActive && profile) {
          setStreakFreezes(profile.streak_freezes || 0);
        }
      }

      // Fetch past streak data
      const now = new Date();
      const dates: string[] = [];
      
      // Tạo mảng 30 ngày qua (bắt đầu từ hôm qua lùi về trước)
      for (let i = 1; i <= 30; i++) {
        const d = new Date(now);
        d.setDate(now.getDate() - i);
        const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        dates.push(dateStr);
      }

      const startOfRange = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 30, 0, 0, 0).toISOString();
      const endOfRange = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 23, 59, 59, 999).toISOString();

      const { data, error } = await supabase
        .from('water_logs')
        .select('day, created_at, amount')
        .eq('user_id', userId)
        .gte('created_at', startOfRange)
        .lte('created_at', endOfRange);

      if (error) {
        console.error("Lỗi tải dữ liệu streak:", error);
        return;
      }

      const dailyTotals = new Map<string, number>();
      (data || []).forEach((log: any) => {
        const amt = Number(log.amount ?? log.amount ?? log.ml ?? 0);
        const logDay = log.day || (
          log.created_at
            ? `${new Date(log.created_at).getFullYear()}-${String(new Date(log.created_at).getMonth() + 1).padStart(2, '0')}-${String(new Date(log.created_at).getDate()).padStart(2, '0')}`
            : null
        );
        if (!logDay) return;

        const current = dailyTotals.get(logDay) || 0;
        dailyTotals.set(logDay, current + (isNaN(amt) ? 0 : amt));
      });

      let currentPastStreak = 0;
      // Đếm lùi từ hôm qua (dates[0])
      for (let i = 0; i < 30; i++) {
        const d = dates[i];
        const total = dailyTotals.get(d) || 0;
        if (total >= waterGoal) currentPastStreak++;
        else break; // Đứt chuỗi ngay khi có 1 ngày không đạt
      }

      if (isActive) {
        setPastStreak(currentPastStreak);
      }
    };

    fetchStreakData();

    return () => {
      isActive = false;
    };
  }, [userId, waterGoal, isPremium]);

  // Tổng Streak = Chuỗi quá khứ + (1 nếu hôm nay đã đạt)
  const streak = useMemo(() => pastStreak + (todayIntake >= waterGoal ? 1 : 0), [pastStreak, todayIntake, waterGoal]);

  // Check if user needs streak freeze (yesterday didn't meet goal and has freezes available)
  const needsFreeze = useMemo(() => {
    if (!isPremium || streakFreezes <= 0) return false;

    // Check if yesterday didn't meet goal (simplified logic)
    // In real implementation, this would check yesterday's intake
    return pastStreak > 0 && todayIntake < waterGoal;
  }, [isPremium, streakFreezes, pastStreak, todayIntake, waterGoal]);

  const useStreakFreeze = async () => {
    if (!isPremium || streakFreezes <= 0 || !needsFreeze) return false;

    // Use one streak freeze
    const newFreezes = streakFreezes - 1;
    const { error } = await supabase
      .from('profiles')
      .update({ streak_freezes: newFreezes })
      .eq('id', userId);

    if (error) {
      console.error('Error using streak freeze:', error);
      return false;
    }

    setStreakFreezes(newFreezes);
    // In real implementation, this would preserve the streak
    return true;
  };

  return {
    streak,
    streakFreezes,
    needsFreeze,
    useStreakFreeze,
    isPremium
  };
}

import { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import type { QuestEngineContext } from '@/lib/questEngine';
import { playWaterDropSound } from '@/lib/audio';
import type { Profile } from '@/models';
import { expGainedForWater } from '@/config/questConfig';
// @ts-ignore
import confetti from 'canvas-confetti';

// ── Constants ──────────────────────────────────────────────

const OFFLINE_QUEUE_KEY = 'digiwell_offline_water_queue';

// ── Types ──────────────────────────────────────────────────

export interface WaterLog {
  id:         string;
  user_id:    string;
  amount:     number;
  name:       string;
  day:        string;
  exp:        number;
  created_at: string;
  timestamp:  string;
  factor:     number;
}

interface OfflineQueueItem {
  tempId:     string;
  user_id:    string;
  amount:     number;
  name:       string;
  exp:        number;
  day:        string;   // FIX: lưu ngay khi push, tránh sai ngày khi sync qua đêm
  created_at: string;
  factor:     number;
  tempC?:     number;
  exerciseMins?: number;
  isFasting?: boolean;
}

// ── Pure helpers ───────────────────────────────────────────

const isRealUser = (id: unknown): id is string =>
  typeof id === 'string' && id.length >= 30;

const toDateStr = (d = new Date()): string =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; // Local date
const normalizeRow = (row: any): WaterLog => {
  const createdAt = row.created_at ?? new Date().toISOString();
  return {
    id:         String(row.id ?? crypto.randomUUID()),
    user_id:    String(row.user_id ?? ''),
    amount:     Number(row.amount ?? 0),
    name:       row.name ?? 'Nuoc Loc',
    day:        row.day ?? toDateStr(new Date(createdAt)),
    exp:        Number(row.exp ?? 0),
    created_at: createdAt,
    timestamp:  row.timestamp ?? createdAt,
    factor:     Number(row.factor ?? 1),
  };
};

// ── Offline queue helpers ──────────────────────────────────

function getOfflineQueueKey(userId: string) {
  return `${OFFLINE_QUEUE_KEY}_${userId}`;
}

function readRawOfflineQueue(storageKey: string): OfflineQueueItem[] {
  try {
    return JSON.parse(localStorage.getItem(storageKey) ?? '[]');
  } catch {
    return [];
  }
}

function readScopedOfflineQueue(userId: string): OfflineQueueItem[] {
  return readRawOfflineQueue(getOfflineQueueKey(userId));
}

function readOfflineQueue(userId: string): OfflineQueueItem[] {
  const scopedQueue = readScopedOfflineQueue(userId);
  const legacyQueue = readRawOfflineQueue(OFFLINE_QUEUE_KEY).filter(item => item.user_id === userId);
  return [...legacyQueue, ...scopedQueue];
}

function pushOfflineQueue(item: OfflineQueueItem) {
  const queue = readScopedOfflineQueue(item.user_id);
  queue.push(item);
  localStorage.setItem(getOfflineQueueKey(item.user_id), JSON.stringify(queue));
}

function clearOfflineQueue(userId: string) {
  localStorage.removeItem(getOfflineQueueKey(userId));

  const legacyQueue = readRawOfflineQueue(OFFLINE_QUEUE_KEY);
  const remainingLegacyItems = legacyQueue.filter(item => item.user_id !== userId);
  if (remainingLegacyItems.length > 0) {
    localStorage.setItem(OFFLINE_QUEUE_KEY, JSON.stringify(remainingLegacyItems));
  } else {
    localStorage.removeItem(OFFLINE_QUEUE_KEY);
  }
}

// ── Hook ───────────────────────────────────────────────────

export function useWaterData(
  profile: (Profile & { water_today?: number }) | null,
  onWaterLogged?: (optimisticAmount?: number, optimisticExp?: number) => void | Promise<void>,
  envFactors: { tempC?: number; exerciseMins?: number; isFasting?: boolean } = {}
) {
  const [waterEntries,        setWaterEntries]        = useState<WaterLog[]>([]);
  const [isSyncing,           setIsSyncing]           = useState(false);
  const [hasPendingCloudSync, setHasPendingCloudSync] = useState(false);

  const mountedRef      = useRef(true);
  const waterIntakeRef  = useRef(0);
  const waterEntriesRef = useRef<WaterLog[]>([]);

  useEffect(() => () => { mountedRef.current = false; }, []);

  // FIX 1: Calculate from waterEntries with fallback to profile
  // Primary: sum of today's waterEntries
  // Fallback: profile.water_today if entries empty (fetch failed)
  const waterIntake = useMemo(() => {
    const fromEntries = waterEntries.reduce((sum, e) => sum + e.amount, 0);
    const fromProfile = profile?.water_today || 0;
    return fromEntries > 0 ? fromEntries : fromProfile;
  }, [waterEntries, profile?.water_today]);



  useEffect(() => {
    waterIntakeRef.current  = waterIntake;
    waterEntriesRef.current = waterEntries;
  }, [waterEntries, waterIntake]);

  useEffect(() => {
    if (!isRealUser(profile?.id)) {
      setHasPendingCloudSync(false);
      return;
    }

    setHasPendingCloudSync(readOfflineQueue(profile.id).length > 0);
  }, [profile?.id]);

  // ── Fetch ──────────────────────────────────────────────

  const fetchAllWater = useCallback(async () => {
    console.log('[useWaterData] fetchAllWater called, profile.id:', profile?.id);
    if (!isRealUser(profile?.id)) {
      console.log('[useWaterData] Not real user, skipping');
      return;
    }

    const today = toDateStr();
    console.log('[useWaterData] Fetching water for today:', today);

    setIsSyncing(true);
    try {
      const { data, error } = await supabase
        .from('water_logs')
        .select('*')
        .eq('user_id', profile.id)
        .eq('day', today)  // Only today's entries
        .order('created_at', { ascending: false });

      if (error) {
        console.error('[useWaterData] fetchAllWater error:', error);
        throw error;
      }

      console.log('[useWaterData] Fetched raw data:', data?.length || 0, 'records for today');
      const normalized = (data ?? []).map(normalizeRow);
      console.log('[useWaterData] Normalized entries:', normalized.length, normalized.slice(0, 3).map((e: WaterLog) => ({ amount: e.amount, name: e.name })));

      setWaterEntries(normalized);
      console.log('[useWaterData] Updated waterEntries state with', normalized.length, 'entries');
    } catch (err) {
      console.error('[useWaterData] fetchAllWater exception:', err);
      toast.error('Không thể tải nhật ký nước. Kiểm tra kết nối.');
      setWaterEntries([]);
    } finally {
      if (mountedRef.current) setIsSyncing(false);
    }
  }, [profile?.id]);

  // Auto fetch water data on mount/profile change
  useEffect(() => {
    if (profile?.id) {
      console.log('[useWaterData] Profile changed, fetching water data');
      fetchAllWater();
    }
  }, [profile?.id, fetchAllWater]);

  // ── Listen to Smart Bottle Events for Optimistic UI ─────
  useEffect(() => {
    const handleSmartBottleEvent = (e: Event) => {
      const customEvent = e as CustomEvent;
      const detail = customEvent.detail;
      
      if (detail?.source === 'smart_bottle' && detail?.amount_ml > 0) {
        const now = detail.occurred_at || new Date().toISOString();
        const newEntry: WaterLog = {
          id: detail.log_id || `bottle-${Date.now()}`,
          user_id: profile?.id || '',
          amount: detail.amount_ml,
          name: 'DigiBottle',
          day: toDateStr(),
          exp: detail.added_exp || 0,
          created_at: now,
          timestamp: now,
          factor: 1,
        };
        
        setWaterEntries(prev => [newEntry, ...prev]);
      }
    };

    window.addEventListener('hydrationEvent', handleSmartBottleEvent);
    return () => {
      window.removeEventListener('hydrationEvent', handleSmartBottleEvent);
    };
  }, [profile?.id]);

  // ── Add water ──────────────────────────────────────────

  const handleAddWater = useCallback(
    async (amount: number, factor = 1, name = 'Nuoc Loc') => {
      if (!profile?.id) return;

      const actualAmount = Math.round(amount * factor);
      if (actualAmount <= 0) return;
      
      const { tempC, exerciseMins, isFasting } = envFactors;

      const exp    = expGainedForWater(actualAmount, profile.level || 1);
      const now    = new Date().toISOString();
      const today  = toDateStr();
      const tempId = `temp-${Date.now()}`;

      // 1. Optimistic UI
      const optimisticEntry: WaterLog = {
        id: tempId, user_id: String(profile.id),
        amount: actualAmount, name, day: today,
        exp, created_at: now, timestamp: now, factor,
      };
      setWaterEntries(prev => [optimisticEntry, ...prev]);
      playWaterDropSound();

      // 2. Demo mode
      if (!isRealUser(profile.id)) {
        toast.success(`💧 +${actualAmount}ml nước!`);
        return;
      }

      // FIX 2: Chỉ gọi onWaterLogged MỘT lần sau khi DB confirm, không gọi trước
      try {
        const { data, error } = await supabase
          .from('water_logs')
          .insert({ user_id: profile.id, amount: actualAmount, name, exp, day: today })
          .select('id')
          .single();

        if (error) throw error;

        // [QUAN TRỌNG] Gọi RPC để backend tự cộng EXP, Level và Coin an toàn tuyệt đối
        const rpcRes = await supabase.rpc('process_hydration_event', {
          p_user_id: profile.id,
          p_amount_ml: actualAmount,
          p_temp_c: tempC || null,
          p_exercise_mins: exerciseMins || 0,
          p_is_fasting: isFasting || false
        });
        if (rpcRes.error) {
          console.error('[useWaterData] RPC process_hydration_event error:', rpcRes.error);
        }

        // Swap tempId -> real ID, không cần refetch toàn bộ
        setWaterEntries(prev =>
          prev.map(e => e.id === tempId ? { ...e, id: String(data.id) } : e),
        );

        toast.success(`💧 +${actualAmount}ml · ⚡ +${exp} EXP!`);

        // Hiệu ứng văng tiền vàng/điểm kinh nghiệm (Coin burst)
        confetti({
          particleCount: 40,
          spread: 70,
          origin: { y: 0.8 }, // Bắn từ nút uống nước (phía dưới màn hình) lên
          colors: ['#fbbf24', '#f59e0b', '#d97706', '#60a5fa'], // Màu vàng Gold, Amber và Xanh dương nhẹ
          shapes: ['circle'], // Hình tròn giống đồng xu
          scalar: 1.2 // Kích thước hạt to hơn một chút
        });

        // Backend RPC da cap nhat progression/profile roi, App chi can refetch
        await onWaterLogged?.();

        // Trigger profile refresh để cập nhật level, exp, coins sau hydration event
        if (typeof window !== 'undefined') {
          window.dispatchEvent(new CustomEvent('hydrationEvent', { detail: { refresh_profile: true } }));
        }

        // Clubs sync: fire & forget, không block UI
        syncToClubs(profile.id, actualAmount).catch(console.error);

      } catch (err) {
        console.error('[useWaterData] addWater:', err);
        toast.error('⚠️ Không thể ghi nhận uống nước. Đã lưu offline để đồng bộ sau.');

        // Rollback optimistic entry
        setWaterEntries(prev => prev.filter(e => e.id !== tempId));

        // FIX 3: Lưu day ngay tại đây thay vì tính lại khi sync
        pushOfflineQueue({
          tempId, user_id: String(profile.id),
          amount: actualAmount, name, exp,
          day: today,
          created_at: now, factor,
          tempC, exerciseMins, isFasting
        });

        setHasPendingCloudSync(true);
      }
    },
    [profile?.id, onWaterLogged],
  );

  // ── Delete ─────────────────────────────────────────────

  const _doDelete = useCallback(
    async (id: string, entry: WaterLog) => {
      const snapshot = waterEntriesRef.current;
      setWaterEntries(prev => prev.filter(e => e.id !== id));

      if (id.startsWith('temp') || !isRealUser(profile?.id)) {
        toast.success('🗑️ Đã xóa thành công!');
        return;
      }

      try {
        console.log('[useWaterData] Deleting entry from DB:', id);
        const { error } = await supabase.from('water_logs').delete().eq('id', id);
        if (error) {
          console.error('[useWaterData] Delete error:', error);
          throw error;
        }

        console.log('[useWaterData] Delete successful, notifying parent');
        // Notify với số âm để parent trừ đúng delta
        await onWaterLogged?.(-entry.amount, -entry.exp);

        // Force refetch to ensure data consistency
        setTimeout(() => fetchAllWater(), 500);

        toast.success('🗑️ Đã xóa thành công!');
      } catch (err) {
        console.error('[useWaterData] Delete failed:', err);
        setWaterEntries(snapshot);
        toast.error('❌ Không thể xóa. Thử lại sau!');
      }
    },
    [profile?.id, onWaterLogged, fetchAllWater],
  );

  const handleDeleteEntry = useCallback(
    async (rawId: unknown) => {
      const id = String(rawId ?? '');
      if (!id) return;

      const entry = waterEntriesRef.current.find(e => e.id === id);
      if (!entry) return;

      toast(`Xóa ${entry.amount}ml ${entry.name}?`, {
        action:   { label: 'Xác nhận', onClick: () => _doDelete(id, entry) },
        cancel:   { label: 'Hủy',      onClick: () => {} },
        duration: 5000,
      });
    },
    [_doDelete],
  );

  // ── Edit ───────────────────────────────────────────────

  const handleEditEntry = useCallback(async (id: string, newAmount: number) => {
    const originalEntry = waterEntriesRef.current.find(e => e.id === id);
    if (!originalEntry) {
      toast.error('Lỗi: Không tìm thấy mục cần sửa.');
      return;
    }

    if (Number.isNaN(newAmount) || newAmount <= 0) {
      toast.error('Lượng nước không hợp lệ.');
      return;
    }

    const newExp      = expGainedForWater(newAmount, profile?.level || 1);
    const snapshot = waterEntriesRef.current;
    // Tính delta để notify parent đúng số chênh lệch, không phải tổng mới
    const deltaAmount = newAmount - originalEntry.amount;
    const deltaExp    = newExp    - originalEntry.exp;

    setWaterEntries(prev =>
      prev.map(e => e.id === id ? { ...e, amount: newAmount, exp: newExp } : e),
    );

    if (!isRealUser(profile?.id) || id.startsWith('temp-')) return;

    try {
      const { error } = await supabase
        .from('water_logs')
        .update({ amount: newAmount, exp: newExp })
        .eq('id', id);

      if (error) throw error;

      toast.success('Đã cập nhật lượng nước!');
      if (deltaAmount !== 0) await onWaterLogged?.(deltaAmount, deltaExp);
    } catch (err) {
      console.error('[useWaterData] edit failed:', err);
      setWaterEntries(snapshot);
      toast.error('❌ Không thể cập nhật. Kiểm tra kết nối!');
    }
  }, [profile?.id, onWaterLogged]);

  // ── Offline sync ───────────────────────────────────────

  const syncOfflineLogs = useCallback(async () => {
    if (!isRealUser(profile?.id)) return;

    const queue = readOfflineQueue(profile.id);
    if (!queue.length) return;

    console.log('[useWaterData] Syncing offline queue:', queue.length, 'items');

    try {
      // Strip tempId và factor (không phải cột DB)
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const payload = queue.map(({ tempId: _t, factor: _f, tempC: _tc, exerciseMins: _em, isFasting: _if, ...rest }) => rest);

      console.log('[useWaterData] Inserting payload:', payload);
      const { error } = await supabase.from('water_logs').insert(payload);
      if (error) {
        console.error('[useWaterData] Insert error:', error);
        throw error;
      }

      // Xử lý cộng EXP cho toàn bộ các lượt uống offline
      for (const item of queue) {
        await supabase.rpc('process_hydration_event', {
          p_user_id: item.user_id,
          p_amount_ml: item.amount,
          p_temp_c: item.tempC || null,
          p_exercise_mins: item.exerciseMins || 0,
          p_is_fasting: item.isFasting || false
        });
      }

      clearOfflineQueue(profile.id);
      setHasPendingCloudSync(false);
      toast.success(`🔄 Đã đồng bộ ${payload.length} mục offline thành công!`);
      // Backend RPC da xu ly tung hydration event, App chi can refetch profile
      await onWaterLogged?.();

      fetchAllWater();
    } catch (err) {
      console.error('[useWaterData] syncOfflineLogs:', err);
      toast.error('📶 Không thể đồng bộ dữ liệu offline. Kiểm tra kết nối mạng!');
    }
  }, [profile?.id, onWaterLogged]);

  useEffect(() => {
    if (hasPendingCloudSync) syncOfflineLogs();
  }, [hasPendingCloudSync, syncOfflineLogs]);

  // ── Return ─────────────────────────────────────────────

  return {
    waterEntries,
    waterIntake,
    handleAddWater,
    handleDeleteEntry,
    handleEditEntry,
    hasPendingCloudSync,
    isSyncing,
    waterIntakeRef,
    waterEntriesRef,
    refetchWater: fetchAllWater,
    syncOfflineLogs,
  };
}

// ── Club sync (fire & forget) ──────────────────────────────

async function syncToClubs(userId: string, amountMl: number) {
  const { data: clubs } = await supabase
    .from('club_members')
    .select('club_id')
    .eq('user_id', userId);

  if (!clubs?.length) return;

  await Promise.allSettled(
    clubs.map(({ club_id }: { club_id: string }) =>
      Promise.all([
        supabase.rpc('increment_club_member_intake', {
          p_user_id: userId, p_club_id: club_id, p_amount_to_add: amountMl,
        }),
        supabase.from('club_activity').insert({
          club_id, user_id: userId,
          activity_type: 'drink',
          message: `da nap them ${amountMl}ml nuoc`,
        }),
      ]),
    ),
  );
}

