function formatDate(d: Date): string {
  return new Intl.DateTimeFormat('vi-VN', { day: '2-digit', month: '2-digit' }).format(d);
}

// src/lib/audio.ts

// Helper để tái sử dụng AudioContext
const getAudioContext = () => {
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  if (!AudioContextClass) return null;
  return new AudioContextClass();
};

// Hàm phát âm thanh ăn mừng bằng Web Audio API
export const playSuccessSound = () => {
  try {
    const ctx = getAudioContext();
    if (!ctx) return;

    const playNote = (freq: number, startTime: number) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, ctx.currentTime + startTime);
      gain.gain.setValueAtTime(0, ctx.currentTime + startTime);
      gain.gain.linearRampToValueAtTime(0.1, ctx.currentTime + startTime + 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + startTime + 0.5);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(ctx.currentTime + startTime);
      osc.stop(ctx.currentTime + startTime + 0.5);
    };

    // Chơi một hợp âm trưởng rải (Arpeggio) vui tai
    playNote(523.25, 0);    // C5
    playNote(659.25, 0.1);  // E5
    playNote(783.99, 0.2);  // G5
    playNote(1046.50, 0.3); // C6
  } catch (e) {
    console.warn("Audio không thể phát:", e);
  }
};

// Hàm phát âm thanh giọt nước
export const playWaterDropSound = () => {
  try {
    const ctx = getAudioContext();
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const now = ctx.currentTime;

    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.4, now + 0.02); // Attack rất nhanh
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2); // Decay

    osc.type = 'sine';
    osc.frequency.setValueAtTime(1200, now); // Bắt đầu cao
    osc.frequency.exponentialRampToValueAtTime(400, now + 0.15); // Giảm nhanh

    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.3);
  } catch (e) {
    console.warn("Audio không thể phát:", e);
  }
};

// =========================================================================
// CÁC HIỆU ỨNG TỔNG HỢP MỚI CHO GAMIFICATION (QUEST, LEVEL UP, HOVER)
// =========================================================================

// Hiệu ứng "Póp" siêu nhẹ khi lướt chuột qua (Hover)
export const playHoverSound = () => {
  try {
    const ctx = getAudioContext();
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const now = ctx.currentTime;

    osc.type = 'sine';
    osc.frequency.setValueAtTime(800, now);
    osc.frequency.exponentialRampToValueAtTime(400, now + 0.05); // Tụtt pitch siêu nhanh
    
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.05, now + 0.01); // Volume rất nhỏ (0.05)
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
    
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.05);
  } catch (e) {}
};

// Hiệu ứng "Ting Ting" sáng và đã tai khi nhận thưởng (Claim)
export const playClaimSound = () => {
  try {
    const ctx = getAudioContext();
    if (!ctx) return;
    
    const playNote = (freq: number, startDelay: number) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle'; // Sóng tam giác cho âm thanh giống chuông (bell)
      
      const startTime = ctx.currentTime + startDelay;
      osc.frequency.setValueAtTime(freq, startTime);
      
      gain.gain.setValueAtTime(0, startTime);
      gain.gain.linearRampToValueAtTime(0.15, startTime + 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, startTime + 0.5);
      
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(startTime);
      osc.stop(startTime + 0.5);
    };

    playNote(880, 0);        // A5
    playNote(1108.73, 0.1);  // C#6
    playNote(1318.51, 0.2);  // E6 (Tạo thành hợp âm A Major sáng chói)
  } catch(e) {}
};

// Hiệu ứng "Siêu năng lượng" (Power-up) khi nhận thưởng Hyper (Critical Hit)
export const playHyperSound = () => {
  try {
    const ctx = getAudioContext();
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const now = ctx.currentTime;

    osc.type = 'square'; // Sóng vuông tạo cảm giác điện tử 8-bit (Retro)
    osc.frequency.setValueAtTime(300, now);
    osc.frequency.linearRampToValueAtTime(1200, now + 0.2); // Vuốt lên cao (Charge up)
    osc.frequency.exponentialRampToValueAtTime(400, now + 0.6); // Rơi xuống (Release)
    
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.15, now + 0.1);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
    
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.6);
  } catch(e) {}
};

// Cổng điều hướng đa năng (Dành cho QuestCard và các module khác gọi)
export const playSound = (name: string, volume: number = 0.5) => {
  switch(name) {
    case 'success': case 'levelup': playSuccessSound(); break;
    case 'drop': case 'click': playWaterDropSound(); break;
    case 'hover': playHoverSound(); break;
    case 'claim': playClaimSound(); break;
    case 'hyper': playHyperSound(); break;
  }
};

function timeToMinutes(time: string): number {
  if (!time || !time.includes(':')) return 0;
  const [hours, minutes] = time.split(':').map(Number);
  return (hours * 60) + minutes;
}

export function rankFeedPosts(posts: any[], followingIds: string[], currentUser?: any) {
  if (!posts || posts.length === 0) return [];

  const now = new Date().getTime();

  const scoredPosts = posts.map(post => {
    let score = 0;

    // 1. Theo dõi (Following) - Tín hiệu cơ bản mạnh nhất
    const isFollowing = followingIds?.includes(post.user_id);
    if (isFollowing) score += 500;

    // 2. Độ mới (Recency) - Giảm điểm dần theo thời gian (Time Decay)
    const postTime = new Date(post.created_at).getTime();
    const hoursAgo = (now - postTime) / (1000 * 60 * 60);
    score += Math.max(0, 200 - (hoursAgo * 5)); // Bài viết mới trong 24h sẽ có lợi thế

    // 3. Lịch sử tương tác (Interaction History)
    const likes = post.likes || 0;
    const comments = post.comments || 0;
    score += (likes * 5) + (comments * 10); // Comment thể hiện sự quan tâm sâu hơn Like

    // ==========================================
    // CÁC TÍN HIỆU CÁ NHÂN HÓA (PERSONALIZATION)
    // ==========================================
    if (currentUser && post.author) {
      // 4. Mức độ vận động (Similar Habits)
      if (post.activity && currentUser.activity && post.activity === currentUser.activity) {
        score += 30; // Cùng mức độ vận động (Vd: Cùng là người tập Gym/Yoga)
      }

      // 5. Cùng chung mục tiêu uống nước (Similar Hydration Goals)
      const postWater = post.hydration_ml || post.value || 0;
      const myGoal = currentUser.water_goal || 2000;
      if (postWater > 0 && myGoal > 0) {
        // Nếu bài viết báo cáo lượng nước ấn tượng (đạt > 80% mục tiêu của chính mình)
        if (postWater >= myGoal * 0.8) score += 40;
      }

      // 6. Tín hiệu Thách đấu (Challenge Interest)
      if (post.type === 'challenge') {
        score += 80; // Ưu tiên hiển thị thách đấu để đẩy mạnh Gamification
      }

      // --- PHASE 7: NEW SIGNALS ---
      // 7. Cùng nhóm tuổi (Same Age Group)
      if (post.author.age && currentUser.age && Math.abs(post.author.age - currentUser.age) <= 5) {
        score += 25;
      }

      // 8. Cùng loại đồ uống (Same Drinks) - Giả định user có favorite_drink
      if (post.drink_type && currentUser.favorite_drink && post.drink_type === currentUser.favorite_drink) {
        score += 20;
      }

      // 9. Cùng lịch trình (Similar Schedule)
      if (post.author.wake_up && currentUser.wakeUp && Math.abs(timeToMinutes(post.author.wake_up) - timeToMinutes(currentUser.wakeUp)) <= 60) {
        score += 15;
      }
    }

    return { ...post, _score: score };
  });

  // Sắp xếp danh sách bài viết theo điểm số giảm dần
  return scoredPosts.sort((a, b) => b._score - a._score);
}

// Logging service that strips logs in production
type LogLevel = 'debug' | 'info' | 'warn' | 'error';

class Logger {
  private isProduction = import.meta.env.PROD;

  private log(level: LogLevel, message: string, ...args: any[]) {
    if (this.isProduction && level === 'debug') return;
    console[level](`[${level.toUpperCase()}] ${message}`, ...args);
  }

  debug(message: string, ...args: any[]) {
    this.log('debug', message, ...args);
  }

  info(message: string, ...args: any[]) {
    this.log('info', message, ...args);
  }

  warn(message: string, ...args: any[]) {
    this.log('warn', message, ...args);
  }

  error(message: string, ...args: any[]) {
    this.log('error', message, ...args);
  }
}

