                      <Bluetooth size={8} /> DigiBottle
                    </span>
                  )}
                </div>
                <p className="text-xs text-slate-500 dark:text-slate-400 font-medium">{formatWaterEntryTime(entry)}</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
