import type { WaterLog } from '../models';
import type { WaterIntakeResult } from '../lib/HydrationEngine';
import { useAppStore } from '../store/useAppStore';
import { useUIStore } from '../store/useUIStore';

interface InsightTabProps {
  isExportingPDF: boolean;
  handleExportPDF: () => void;
  isAiLoading: boolean;
  aiAdvice: string;
  fetchAIAdvice: () => void;
  weeklyReport: HealthReport | null;
  isWeeklyReportLoading: boolean;
  generateWeeklyReport: () => void;
}

const glassCard = "bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-2xl shadow-xl";

const InsightTab = memo(function InsightTab({
  isExportingPDF, handleExportPDF,
  isAiLoading, aiAdvice, fetchAIAdvice,
  weeklyReport, isWeeklyReportLoading, generateWeeklyReport
}: InsightTabProps) {
  
  const { profile, isPremium, waterGoal, weeklyHistory: weeklyChartData, streak, hydrationResult, waterIntake } = useAppStore();
  const { setShowPremiumModal, setShowAiChat } = useUIStore();
  const progress = Math.min((waterIntake / (waterGoal || 1)) * 100, 100);
  
  const [timeRange, setTimeRange] = useState<'week' | 'month'>('week');
  const [isStreakModalOpen, setIsStreakModalOpen] = useState(false);
  const [activeWorkout, setActiveWorkout] = useState<string | null>(null);

  // --- STATES CHO MODAL LỊCH SỬ NGÀY ---
  const [selectedDateModal, setSelectedDateModal] = useState<{date: string, ml: number} | null>(null);
  const [dayLogs, setDayLogs] = useState<WaterLog[]>([]);
  const [isDayLogsLoading, setIsDayLogsLoading] = useState(false);

  const [customSchedule, setCustomSchedule] = useState<any[]>([]);
  const [isEditingSchedule, setIsEditingSchedule] = useState(false);
  const [isScheduleOpen, setIsScheduleOpen] = useState(false);

  useEffect(() => {
    // Khôi phục lại lịch trình đã lưu từ bộ nhớ đệm
    const saved = localStorage.getItem(`digiwell_custom_schedule_${profile?.id}`);
    if (saved) {
      try { setCustomSchedule(JSON.parse(saved)); } catch(e) {}
    } else if (hydrationResult?.schedule && customSchedule.length === 0) {
      setCustomSchedule(hydrationResult.schedule);
    }
  }, [hydrationResult, profile?.id]);

  const handleUpdateScheduleItem = (index: number, field: string, value: any) => {
    const newSchedule = [...customSchedule];
    newSchedule[index] = { ...newSchedule[index], [field]: value };
    setCustomSchedule(newSchedule);
  };

  const handleRemoveScheduleItem = (index: number) => {
    setCustomSchedule(customSchedule.filter((_, i) => i !== index));
  };

  const handleAddScheduleItem = () => {
    const newSchedule = [...customSchedule].sort((a, b) => a.time.localeCompare(b.time));
    const lastTime = newSchedule.length > 0 ? newSchedule[newSchedule.length - 1].time : "08:00";
    let [h, m] = lastTime.split(':').map(Number);
    h = (h + 1) % 24;
    const nextTime = `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
    setCustomSchedule([...customSchedule, { time: nextTime, amount: 200, label: 'Mốc mới' }]);
  };

  const handleSaveSchedule = async () => {
    setIsEditingSchedule(false);
    
    // 1. Lưu cục bộ để không mất data khi tắt app
    if (profile?.id) {
      localStorage.setItem(`digiwell_custom_schedule_${profile.id}`, JSON.stringify(customSchedule));
    }

    try {
      // 2. Yêu cầu hệ điều hành cấp quyền Push Notification
      const perm = await LocalNotifications.requestPermissions();
      if (perm.display !== 'granted') {
        toast.warning('Sếp chưa cấp quyền thông báo nên app không thể rung được nhé!');
        return;
      }

      // 3. Xóa sạch các mốc nhắc nhở lịch trình cũ (Dùng ID từ 1000 -> 1050 để phân biệt)
      const pending = await LocalNotifications.getPending();
      const oldNotifs = pending.notifications.filter(n => n.id >= 1000 && n.id <= 1050);
      if (oldNotifs.length > 0) {
        await LocalNotifications.cancel({ notifications: oldNotifs });
      }

      // Đăng ký các nút bấm (Actions) cho thông báo với hệ điều hành
      await LocalNotifications.registerActionTypes({
        types: [{
          id: 'SCHEDULE_REMINDER_ACTIONS',
          actions: [
            { id: 'add_100', title: '💧 Uống 100ml' },
            { id: 'add_250', title: '💧 Uống 250ml' },
            { id: 'snooze_10', title: '💤 Nhắc sau 10 phút' }
          ]
        }]
      });

      const equippedSound = profile?.equipped_notification_sound || 'water_drop.wav';

      // 4. Lên lịch thông báo lặp lại hàng ngày theo mốc giờ
      const notificationsToSchedule = customSchedule.map((item, index) => {
        const [hour, minute] = item.time.split(':').map(Number);
        return {
          id: 1000 + index, // Gắn ID định danh
          title: '💧 DigiWell - Đến giờ nạp nước!',
          body: item.note || `Đã đến mốc ${item.time}. Hãy nạp ${item.amount}ml nước sếp nhé!`,
          schedule: { on: { hour, minute }, allowWhileIdle: true }, // allowWhileIdle: Cho phép rung kể cả khi máy đang khóa màn hình
          sound: equippedSound, // 🎵 Cấu hình âm thanh tùy chỉnh
          actionTypeId: 'SCHEDULE_REMINDER_ACTIONS', // Liên kết thông báo với bộ nút bấm vừa tạo
          extra: { amount: item.amount, name: item.note || item.label || 'Nước lọc' }
        };
      });

      if (notificationsToSchedule.length > 0) {
        await LocalNotifications.schedule({ notifications: notificationsToSchedule });
      }
      toast.success("✅ Đã kích hoạt Push Notification cho lịch trình!");
    } catch (err) {
      console.error("Lỗi Push Notification:", err);
      toast.error("Đã lưu nhưng tính năng thông báo không được hỗ trợ trên thiết bị này.");
    }
  };

  // --- THUẬT TOÁN TRUE CALENDAR: Tự động tạo lưới lịch chuẩn theo Tháng hiện tại ---
  const { calendarCells, currentMonthName } = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const todayDate = now.getDate();
    
    // Tìm số ngày trong tháng (tự động 28, 29, 30, 31)
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    // Tìm thứ của ngày mùng 1 (0 = CN, 1 = T2...). Đổi sang T2 là đầu tuần (0 = T2... 6 = CN)
    let firstDayIndex = new Date(year, month, 1).getDay() - 1;
    if (firstDayIndex === -1) firstDayIndex = 6; 

    const cells = [];
    
    // 1. Lấp đầy các ô trống ở đầu tháng
    for (let i = 0; i < firstDayIndex; i++) {
      cells.push({ dayNum: null, ml: 0, isFuture: false, isToday: false, isEmptySlot: true, fullDate: '' });
    }

    // Lấy data tuần ngược lại để map vào các ngày gần đây
    const weeklyDataReversed = [...weeklyChartData].reverse();

    // 2. Điền các ngày trong tháng
    for (let i = 1; i <= daysInMonth; i++) {
      const isFuture = i > todayDate;
      const isToday = i === todayDate;
      let ml = 0;

      // Map data từ weeklyChartData vào đúng ngày (chỉ mô phỏng cho 7 ngày gần nhất)
      const daysAgo = todayDate - i;
      if (daysAgo >= 0 && daysAgo < weeklyDataReversed.length) {
        ml = weeklyDataReversed[daysAgo]?.ml || 0;
      }

      const fullDateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      cells.push({ dayNum: i, ml, isFuture, isToday, isEmptySlot: false, fullDate: fullDateStr });
    }

    const monthNames = ['Tháng 1', 'Tháng 2', 'Tháng 3', 'Tháng 4', 'Tháng 5', 'Tháng 6', 'Tháng 7', 'Tháng 8', 'Tháng 9', 'Tháng 10', 'Tháng 11', 'Tháng 12'];

    return { 
      calendarCells: cells, 
      currentMonthName: `${monthNames[month]} / ${year}` 
    };
  }, [weeklyChartData]);

  // --- HÀM LẤY CHI TIẾT LỊCH SỬ NGÀY KHI BẤM VÀO LỊCH ---
