                <p className="text-3xl font-black text-white">{averageWp.toLocaleString()}</p>
              </div>
            </div>
          </div>

          {/* Mode tabs - increased touch target */}
          <div className="flex p-1.5 bg-slate-900/60 backdrop-blur-xl rounded-2xl border border-white/10 mx-1 shadow-2xl relative">
